87	    87	    /** The people with their dated grades, the grade in force on the sheet's today, their holds and their aliases. */
88	    88	    private List<Person> graded(String sheetId, List<Person> people) {
89	    89	        if (people.isEmpty()) {
90	    90	            return people;
91	    91	        }
92	    92	        LocalDate today = jdbc.query("SELECT today FROM sheet WHERE id = ?",
93	    93	                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
94	    94	        Map<Long, List<Grades.Grade>> byPerson = jdbc.query(
95	    95	                "SELECT * FROM person_grade WHERE sheet_id = ? ORDER BY person_id, from_date NULLS FIRST", GRADE_ROW,
96	    96	                sheetId).stream().collect(Collectors.groupingBy(GradeRow::personId,
97	    97	                        Collectors.mapping(GradeRow::grade, Collectors.toList())));
98	    98	        Map<Long, List<Holds.Hold>> holdsByPerson = jdbc.query(
99	    99	                "SELECT * FROM person_hold WHERE sheet_id = ? ORDER BY person_id, id", HOLD_ROW, sheetId).stream()
100	   100	                .collect(Collectors.groupingBy(HoldRow::personId,
101	   101	                        Collectors.mapping(HoldRow::hold, Collectors.toList())));
102	   102	        Map<Long, List<Terms.Dated>> termsByPerson = datedTerms(sheetId);
103	   103	        Map<Long, List<String>> aliasesByPerson = aliases(sheetId, null);
104	   104	        Map<Long, List<Person.Retirement>> retirementsByPerson = retirements(sheetId, null);
105	   105	        Map<Long, List<Person.StatementLine>> statementsByPerson = jdbc.query(
106	   106	                "SELECT person_id, due_total, statement_date FROM person_statement WHERE sheet_id = ? AND NOT cancelled "
107	   107	                        + "ORDER BY person_id, id", STATEMENT_ROW, sheetId).stream()
108	   108	                .collect(Collectors.groupingBy(StatementRow::personId,
109	   109	                        Collectors.mapping(StatementRow::line, Collectors.toList())));
110	   110	        return people.stream().map(p -> {
111	   111	            Grades grades = new Grades(byPerson.getOrDefault(p.id(), List.of()));
112	   112	            return new Person(p.id(), p.sheetId(), p.name(), grades.on(today), p.version(), p.statementCount(),
113	   113	                    p.statedTotal(), p.statementDate(), p.retiredFrom(), grades,
114	   114	                    new Holds(holdsByPerson.getOrDefault(p.id(), List.of())),
115	   115	                    new Terms(p.terms().base(), termsByPerson.getOrDefault(p.id(), List.of()), null).shownOn(today),
116	   116	                    p.contact(),
117	   117	                    aliasesByPerson.getOrDefault(p.id(), List.of()), p.origin(),
118	   118	                    retirementsByPerson.getOrDefault(p.id(), List.of()), p.tags(),
119	   119	                    statementsByPerson.getOrDefault(p.id(), List.of()));
120	   120	        }).toList();
121	   121	    }
