123	   123	    /** Set the person's tags (joined by commas; null: none), keeping each among the tags ever used on the sheet. */
124	   124	    public void tags(Person person, String tags) {
125	   125	        jdbc.update("UPDATE person SET tags = ? WHERE sheet_id = ? AND id = ?", tags, person.sheetId(), person.id());
126	   126	        if (tags != null) {
127	   127	            for (String tag : tags.split(",")) {
128	   128	                jdbc.update("MERGE INTO claim_tag KEY (sheet_id, tag) VALUES (?, ?)", person.sheetId(), tag);
129	   129	            }
