133	   133	    /** Whether another person on this sheet (other than exceptId, when given) has this name, or anyone on the sheet
134	   134	     *  has it as an alias, compared without regard to case and ignoring surrounding spaces. */
135	   135	    public boolean nameInUse(String sheetId, String name, Long exceptId) {
136	   136	        Integer n = jdbc.queryForObject(
137	   137	                "SELECT (SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(TRIM(?)) AND id <> ?) "
138	   138	                        + "+ (SELECT COUNT(*) FROM person_alias WHERE sheet_id = ? AND alias_key = LOWER(TRIM(?)))",
139	   139	                Integer.class, sheetId, name, exceptId == null ? -1L : exceptId, sheetId, name);
140	   140	        return n != null && n > 0;
141	   141	    }
