143	   143	    /** The other sheets of the sheet's tree, among those that exist: its ancestors (its parent, its parent's parent,
144	   144	     *  and so on) and its descendants (the sheets naming it as their parent, their children, and so on). */
145	   145	    public List<String> tree(String sheetId) {
146	   146	        java.util.Set<String> seen = new java.util.LinkedHashSet<>();
147	   147	        seen.add(sheetId);
148	   148	        for (String at = parentOf(sheetId); at != null && seen.add(at); at = parentOf(at)) {
149	   149	        }
150	   150	        java.util.Deque<String> next = new java.util.ArrayDeque<>(List.of(sheetId));
151	   151	        while (!next.isEmpty()) {
152	   152	            for (String child : jdbc.queryForList("SELECT id FROM sheet WHERE parent = ? ORDER BY id", String.class,
153	   153	                    next.removeFirst())) {
154	   154	                if (seen.add(child)) {
155	   155	                    next.addLast(child);
156	   156	                }
157	   157	            }
158	   158	        }
159	   159	        seen.remove(sheetId);
160	   160	        return seen.stream().filter(id -> jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?",
161	   161	                Integer.class, id) > 0).toList();
162	   162	    }
163	   163	
164	   164	    private String parentOf(String sheetId) {
165	   165	        return jdbc.query("SELECT parent FROM sheet WHERE id = ?", rs -> rs.next() ? rs.getString(1) : null, sheetId);
166	   166	    }
