214	   214	    /** Add a person with their first grade, which applies from the beginning of time, their own terms (null: none)
215	   215	     *  and their contact (null: none). */
216	   216	    public Person insert(String sheetId, String name, String grade, Integer terms, String contact) {
217	   217	        var keys = new GeneratedKeyHolder();
218	   218	        jdbc.update(con -> {
219	   219	            var ps = con.prepareStatement("INSERT INTO person (sheet_id, name, terms, contact, added_on, list_position) VALUES (?, ?, ?, ?, "
220	   220	                    + "(SELECT today FROM sheet WHERE id = ?), " + END_POSITION + ")",
221	   221	                    new String[] { "id" });
222	   222	            ps.setString(1, sheetId);
223	   223	            ps.setString(2, name);
224	   224	            ps.setObject(3, terms, java.sql.Types.INTEGER);
225	   225	            ps.setString(4, contact);
226	   226	            ps.setString(5, sheetId);
227	   227	            ps.setString(6, sheetId);
228	   228	            return ps;
229	   229	        }, keys);
230	   230	        long id = keys.getKey().longValue();
231	   231	        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, grade, from_date) VALUES (?, ?, ?, NULL)",
232	   232	                sheetId, id, grade);
233	   233	        jdbc.update("INSERT INTO person_grade_log (sheet_id, person_id, grade, from_date, made_on) VALUES (?, ?, ?, NULL, "
234	   234	                + "(SELECT today FROM sheet WHERE id = ?))", sheetId, id, grade, sheetId);
235	   235	        return new Person(id, sheetId, name, grade, 0, 0, null, null, null,
236	   236	                new Grades(List.of(new Grades.Grade(grade, null))), Holds.NONE, Terms.of(terms), contact, List.of(), null,
237	   237	                List.of(), null, List.of());
238	   238	    }
