246	   246	    /** Record a statement taken of the person: one more taken, with its due-total (null: n/a) and date. Leaves the version alone: a statement is not an edit of the person. */
247	   247	    public void stated(Person person, BigDecimal total, LocalDate date) {
248	   248	        jdbc.update("UPDATE person SET statement_count = statement_count + 1, stated_total = ?, statement_date = ? "
249	   249	                + "WHERE sheet_id = ? AND id = ?", total, date, person.sheetId(), person.id());
250	   250	        jdbc.update("INSERT INTO person_statement (sheet_id, person_id, due_total, statement_date, made_on) VALUES (?, ?, ?, ?, "
