254	   254	    /** Cancel the last statement taken of the person: one fewer taken, and their row shows the one before it (its
255	   255	     *  due-total and date; none when there is no earlier one kept). The cancelled one is kept, marked cancelled with
256	   256	     *  the sheet's today. Leaves the version alone. */
257	   257	    public void unstated(Person person) {
258	   258	        List<Long> kept = jdbc.queryForList("SELECT id FROM person_statement WHERE sheet_id = ? AND person_id = ? "
259	   259	                + "AND NOT cancelled ORDER BY id DESC", Long.class, person.sheetId(), person.id());
260	   260	        if (!kept.isEmpty()) {
261	   261	            jdbc.update("UPDATE person_statement SET cancelled = TRUE, cancelled_on = (SELECT today FROM sheet WHERE id = ?) "
262	   262	                    + "WHERE id = ?", person.sheetId(), kept.get(0));
263	   263	        }
264	   264	        jdbc.update("UPDATE person SET statement_count = statement_count - 1, stated_total = NULL, statement_date = NULL "
265	   265	                + "WHERE sheet_id = ? AND id = ? AND statement_count > 0", person.sheetId(), person.id());
266	   266	        if (kept.size() > 1) {
267	   267	            jdbc.update("UPDATE person SET stated_total = (SELECT due_total FROM person_statement WHERE id = ?), "
268	   268	                    + "statement_date = (SELECT statement_date FROM person_statement WHERE id = ?) "
269	   269	                    + "WHERE sheet_id = ? AND id = ?", kept.get(1), kept.get(1), person.sheetId(), person.id());
270	   270	        }
271	   271	    }
