298	   298	    /** Merge the person (their claims, patrons, pools and watchers already dealt with) into another: their aliases
299	   299	     *  and then their name become the other's aliases, their figures in closed periods are added to the other's,
300	   300	     *  their statements are added to the other's count (the other's last statement stays theirs or, having none,
301	   301	     *  becomes theirs, with its history), and they leave the sheet with their grades, holds, retirement and contact. */
302	   302	    public void merge(Person from, Person into) {
303	   303	        String sheetId = from.sheetId();
304	   304	        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet_id = ? AND person_id = ?", into.id(), sheetId,
305	   305	                from.id());
306	   306	        jdbc.update("UPDATE period_person_total t SET total = total + (SELECT f.total FROM period_person_total f "
307	   307	                + "WHERE f.sheet_id = t.sheet_id AND f.period_name = t.period_name AND f.person_id = ?), "
308	   308	                + "carried = CASE WHEN carried IS NULL THEN NULL ELSE carried + COALESCE((SELECT f.carried FROM "
309	   309	                + "period_person_total f WHERE f.sheet_id = t.sheet_id AND f.period_name = t.period_name "
310	   310	                + "AND f.person_id = ?), 0) END "
311	   311	                + "WHERE sheet_id = ? AND person_id = ? AND EXISTS (SELECT 1 FROM period_person_total f "
312	   312	                + "WHERE f.sheet_id = t.sheet_id AND f.period_name = t.period_name AND f.person_id = ?)",
313	   313	                from.id(), from.id(), sheetId, into.id(), from.id());
314	   314	        jdbc.update("DELETE FROM period_person_total f WHERE sheet_id = ? AND person_id = ? AND EXISTS (SELECT 1 "
315	   315	                + "FROM period_person_total t WHERE t.sheet_id = f.sheet_id AND t.period_name = f.period_name "
316	   316	                + "AND t.person_id = ?)", sheetId, from.id(), into.id());
317	   317	        jdbc.update("UPDATE period_person_total SET person_id = ? WHERE sheet_id = ? AND person_id = ?", into.id(),
318	   318	                sheetId, from.id());
319	   319	        jdbc.update("UPDATE period_person_opening SET person_id = ? WHERE sheet_id = ? AND person_id = ?", into.id(),
320	   320	                sheetId, from.id());
321	   321	        joinStatements(from, into);
322	   322	        for (String table : List.of("person_grade", "person_grade_log", "person_hold", "person_flag", "person_approver", "person_statement", "person_terms",
323	   323	                "person_retire_log", "person_retirement")) {
324	   324	            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", sheetId, from.id());
325	   325	        }
326	   326	        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, from.id());
327	   327	        alias(into, from.name());
328	   328	    }
