330	   330	    /** Add the person's statements to another's count (on this sheet or another): the other's last statement stays
331	   331	     *  theirs or, when they have none, becomes the person's, whose statements (with their history) go to them. */
332	   332	    private void joinStatements(Person from, Person into) {
333	   333	        if (into.statementCount() == 0) {
334	   334	            jdbc.update("UPDATE person SET statement_count = statement_count + ?, stated_total = ?, statement_date = ? "
335	   335	                    + "WHERE sheet_id = ? AND id = ?", from.statementCount(), from.statedTotal(), from.statementDate(),
336	   336	                    into.sheetId(), into.id());
337	   337	            jdbc.update("UPDATE person_statement SET sheet_id = ?, person_id = ? WHERE sheet_id = ? AND person_id = ?",
338	   338	                    into.sheetId(), into.id(), from.sheetId(), from.id());
339	   339	        } else {
340	   340	            jdbc.update("UPDATE person SET statement_count = statement_count + ? WHERE sheet_id = ? AND id = ?",
