78	    /** Re-fix the due-by of each of the sheet's claims not SETTLED or VOID whose due-by is on or after the holiday:
79	     *  worked out again from its date, with the terms it was fixed with, over the sheet's holidays as they are now. */
80	    public void refixDueBys(String sheetId, LocalDate holiday) {
81	        var dates = holidays.dates(sheetId);
82	        record Fixed(long id, LocalDate dueBy) {
83	        }
84	        List<Fixed> moved = new java.util.ArrayList<>();
85	        jdbc.query("SELECT id, due_from, terms_days, due_by FROM claim WHERE sheet_id = ? AND due_by >= ? AND status NOT IN (?, ?)",
86	                rs -> {
87	                    LocalDate now = BusinessDays.after(rs.getObject("due_from", LocalDate.class), rs.getInt("terms_days"), dates);
88	                    if (!now.equals(rs.getObject("due_by", LocalDate.class))) {
89	                        moved.add(new Fixed(rs.getLong("id"), now));
90	                    }
91	                }, sheetId, holiday, ClaimStatus.SETTLED.name(), ClaimStatus.VOID.name());
92	        for (Fixed f : moved) {
93	            jdbc.update("UPDATE claim SET due_by = ? WHERE sheet_id = ? AND id = ?", f.dueBy(), sheetId, f.id());
94	            kept(sheetId, f.id());
95	        }
96	    }
