98	    /** Store a new claim fixed with the terms (business days), counted from its date. */
99	    public Claim insert(int terms, Claim claim) {
100	        var keys = new GeneratedKeyHolder();
101	        jdbc.update(con -> {
102	            var ps = con.prepareStatement(
103	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects, due_from, terms_days, split_from, late_entry, ref, tags, due_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
104	                    new String[] { "id" });
105	            ps.setString(1, claim.sheetId());
106	            ps.setLong(2, claim.personId());
107	            ps.setBigDecimal(3, claim.amount());
108	            ps.setObject(4, claim.date());
109	            ps.setString(5, claim.note());
110	            ps.setString(6, claim.corrects());
111	            ps.setObject(7, claim.date());
112	            ps.setInt(8, terms);
113	            ps.setString(9, claim.splitFrom());
114	            ps.setBoolean(10, claim.lateEntry());
115	            ps.setString(11, claim.ref());
116	            ps.setString(12, claim.tags());
117	            ps.setObject(13, claim.dueBy());
118	            return ps;
119	        }, keys);
120	        kept(claim.sheetId(), keys.getKey().longValue());
121	        used(claim.sheetId(), claim.tags());
122	        return new Claim(keys.getKey().longValue(), claim.sheetId(), claim.personId(), claim.amount(),
123	                claim.date(), claim.note(), ClaimStatus.DRAFT, null, null, null, false, null, claim.corrects(),
124	                claim.dueBy(), null, 0, claim.splitFrom(), claim.lateEntry(), null, claim.ref(), claim.tags(), false, 0, false);
125	    }
