188	    /** Move every claim of the person to another sheet, keeping its place in their list, its status, dates, note,
189	     *  settled due, tags, comments, lines and log: each claim that had a number takes the next number of the other sheet,
190	     *  in the order the claims were added; each keeps the figure a statement bound it to, loses its reference, editor lock and
191	     *  settle batch, and its history here is dropped (it is kept anew on the other sheet). */
192	    public void transfer(String sheetId, long personId, String toSheet) {
193	        List<Claim> theirs = listForPerson(sheetId, personId).stream()
194	                .sorted(java.util.Comparator.comparingLong(Claim::id)).toList();
195	        for (Claim c : theirs) {
196	            String number = c.number() != null ? nextNumber(toSheet, c.dueBy()) : null;
197	            jdbc.update("UPDATE claim SET sheet_id = ?, claim_number = ?, due_by = ?, "
198	                    + "ref = NULL, locked_by = NULL WHERE sheet_id = ? AND id = ?", toSheet, number, c.dueBy(), sheetId,
199	                    c.id());
200	            for (String table : List.of("claim_log", "claim_comment", "claim_line", "claim_void_reason")) {
201	                jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND claim_id = ?", toSheet,
202	                        sheetId, c.id());
203	            }
204	            for (String table : List.of("claim_batch", "claim_history")) {
205	                jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND claim_id = ?", sheetId, c.id());
206	            }
207	            kept(toSheet, c.id());
208	            used(toSheet, c.tags());
209	        }
210	    }
