330	    /** Take the next number for a claim due by the date, as it is opened. While the sheet's period numbering from
331	     *  is a date and the sheet's today is on or after it, that is the next in the claim's period (the one holding its due-by: <period name>-<n>),
332	     *  or for a claim in no period the next in its own sequence (X-<n>); otherwise it is the next number of the
333	     *  sheet's tree (the sheet's root, reached through its parents, and every descendant of the root) within the
334	     *  fiscal year of the due-by (by this sheet's fiscal year start month): FY<yyyy>-<n>, one after the last number
335	     *  given in that fiscal year on any sheet of the tree, recorded as this sheet's last number for that year.
336	     *  Taking a number locks the sheet's row (and, for a tree number, every row of the tree, in id order) until the
337	     *  transaction ends, so concurrent openings are numbered one after the other; a rolled-back one gives its number
338	     *  back, so there are no gaps. */
339	    public String nextNumber(String sheetId, LocalDate date) {
340	        jdbc.query("SELECT id FROM sheet WHERE id = ? FOR UPDATE", rs -> null, sheetId);
341	        Boolean byPeriod = jdbc.query(
342	                "SELECT period_numbering_from IS NOT NULL AND today >= period_numbering_from FROM sheet WHERE id = ?",
343	                rs -> rs.next() ? rs.getBoolean(1) : false, sheetId);
344	        if (!Boolean.TRUE.equals(byPeriod)) {
345	            Set<String> tree = tree(sheetId);
346	            String in = String.join(",", Collections.nCopies(tree.size(), "?"));
347	            Object[] ids = tree.toArray();
348	            jdbc.query("SELECT id FROM sheet WHERE id IN (" + in + ") ORDER BY id FOR UPDATE", rs -> null, ids);
349	            int fy = fiscalYear(sheetId, date);
350	            Object[] args = new Object[ids.length + 1];
351	            System.arraycopy(ids, 0, args, 0, ids.length);
352	            args[ids.length] = fy;
353	            Integer last = jdbc.queryForObject("SELECT MAX(last_number) FROM fiscal_year_number WHERE sheet_id IN ("
354	                    + in + ") AND fiscal_year = ?", Integer.class, args);
355	            int next = (last == null ? 0 : last) + 1;
356	            if (jdbc.update("UPDATE fiscal_year_number SET last_number = ? WHERE sheet_id = ? AND fiscal_year = ?",
357	                    next, sheetId, fy) == 0) {
358	                jdbc.update("INSERT INTO fiscal_year_number (sheet_id, fiscal_year, last_number) VALUES (?, ?, ?)",
359	                        sheetId, fy, next);
360	            }
361	            return "FY" + fy + "-" + next;
362	        }
363	        String[] period = jdbc.query(
364	                "SELECT name, name_key FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ? ORDER BY from_date",
365	                rs -> rs.next() ? new String[] { rs.getString(1), rs.getString(2) } : null, sheetId, date, date);
366	        String prefix = period != null ? period[0] : "X";
367	        String key = period != null ? "p:" + period[1] : "x";
368	        if (jdbc.update("UPDATE period_number SET last_number = last_number + 1 WHERE sheet_id = ? AND seq_key = ?",
369	                sheetId, key) == 0) {
370	            jdbc.update("INSERT INTO period_number (sheet_id, seq_key, last_number) VALUES (?, ?, 1)", sheetId, key);
371	        }
372	        int n = jdbc.queryForObject("SELECT last_number FROM period_number WHERE sheet_id = ? AND seq_key = ?",
373	                Integer.class, sheetId, key);
374	        return prefix + "-" + n;
375	    }
