377	    /** The fiscal year holding the date by the sheet's fiscal year start month, named by the calendar year its
378	     *  first day falls in. */
379	    private int fiscalYear(String sheetId, LocalDate date) {
380	        Integer month = jdbc.query("SELECT fiscal_start_month FROM sheet WHERE id = ?",
381	                rs -> rs.next() ? (Integer) rs.getObject(1, Integer.class) : null, sheetId);
382	        int start = month != null ? month : 1;
383	        return date.getMonthValue() >= start ? date.getYear() : date.getYear() - 1;
384	    }
