386	    /** The sheets of the sheet's tree, in id order: its root (its parent's parent, and so on, up to a sheet with
387	     *  none) and every descendant of the root. */
388	    private Set<String> tree(String sheetId) {
389	        Set<String> up = new LinkedHashSet<>();
390	        String root = sheetId;
391	        for (String at = sheetId; at != null && up.add(at); at = parentOf(at)) {
392	            root = at;
393	        }
394	        Set<String> tree = new TreeSet<>();
395	        Deque<String> todo = new ArrayDeque<>(List.of(root));
396	        while (!todo.isEmpty()) {
397	            String at = todo.pop();
398	            if (tree.add(at)) {
399	                todo.addAll(jdbc.queryForList("SELECT id FROM sheet WHERE parent = ?", String.class, at));
400	            }
401	        }
402	        tree.add(sheetId);
403	        return tree;
404	    }
