182	    static void audit(ClaimStatusInput input, Claim loaded, ClaimResponse saved, PersonRepository people,
183	            WatchRepository watches, Audit audit) {
184	        var person = people.find(loaded.sheetId(), loaded.personId());
185	        String event = switch (input.action()) {
186	            case "open" -> "REVIEW".equals(saved.status()) ? "CLAIM_REVIEW" : "CLAIM_OPENED";
187	            case "review" -> "CLAIM_OPENED";
188	            case "settle" -> "PENDING".equals(saved.status()) ? "CLAIM_PENDING" : "CLAIM_SETTLED";
189	            case "approve" -> "CLAIM_APPROVED";
190	            case "reject" -> "CLAIM_REJECTED";
191	            case "resettle" -> "CLAIM_RESETTLED";
192	            case "void" -> "CLAIM_VOIDED";
193	            case "delete" -> "CLAIM_DELETED";
194	            case "restore" -> "CLAIM_RESTORED";
195	            default -> throw new IllegalStateException("Unknown claim action: " + input.action() + ".");
196	        };
197	        boolean resettled = input.action().equals("resettle");
198	        boolean reversed = input.action().equals("void") && loaded.status() == ClaimStatus.SETTLED;
199	        boolean settled = "SETTLED".equals(saved.status()) && !resettled;
200	        String number = saved.number() != null ? saved.number() : loaded.number();
201	        if (input.action().equals("review")) {
202	            audit.record("CLAIM_REVIEWED sheet=" + loaded.sheetId() + " by=" + input.user()
203	                    + " person=" + person.name() + " amount=" + saved.amount() + " date=" + saved.date());
204	        }
205	        audit.record(event + " sheet=" + loaded.sheetId() + " by=" + input.user()
206	                + " person=" + person.name() + " amount=" + saved.amount() + " date=" + saved.date()
207	                + (number != null ? " number=" + number : "")
208	                + (settled ? " due=" + (saved.settledDue() != null ? saved.settledDue() : "n/a") : "")
209	                + (input.reason() != null && !input.action().equals("void") ? " reason=" + input.reason() : "")
210	                + (resettled ? " old=" + (loaded.settledDue() != null ? loaded.settledDue() : "n/a")
211	                        + " new=" + (saved.settledDue() != null ? saved.settledDue() : "n/a") : "")
212	                + (reversed ? " reversed=" + (loaded.settledDue() != null ? loaded.settledDue() : "n/a") : "")
213	                + (input.reason() != null && input.action().equals("void") ? " reason=" + input.reason() : "")
214	                + (settled && input.on() != null ? " on=" + input.on() : ""));
215	        if (event.equals("CLAIM_SETTLED") || event.equals("CLAIM_APPROVED") || event.equals("CLAIM_RESETTLED")) {
216	            for (String watcher : watches.watchers(loaded.sheetId(), loaded.personId())) {
217	                audit.record("NOTIFY sheet=" + loaded.sheetId() + " by=" + input.user() + " user=" + watcher
218	                        + " person=" + person.name() + " number=" + number);
219	            }
220	        }
221	    }
