    22	/** Takes the sheet's figures, and records in the audit file how they moved over a change: a ROLLUP line per
    23	 *  person whose figures (claimed, due-total, overdue-total) changed (a person new to the sheet counting as changed), in the order they were added,
    24	 *  then a TOTALS line when the sheet's totals changed (its due-total and overdue-total leave out the single highest and
    25	 *  single lowest person's figure when three or more people have one; n/a is no figure), then, when the sheet has an
    26	 *  alert threshold, an ALERT line per person whose due-total went from at or below it (or none) to above it, in
    27	 *  list order. A change that moves no figure records nothing. */
    28	@Service
    29	public class Rollups {
    30	
    31	    private final PersonRepository people;
    32	    private final ClaimRepository claims;
    33	    private final RateRepository rates;
    34	    private final SheetRepository sheets;
    35	    private final SettingRepository settings;
    36	    private final Audit audit;
    37	
    38	    public Rollups(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
    39	            SettingRepository settings, Audit audit) {
    40	        this.people = people;
    41	        this.claims = claims;
    42	        this.rates = rates;
    43	        this.sheets = sheets;
    44	        this.settings = settings;
    45	        this.audit = audit;
    46	    }
    47	
    48	    /** The sheet's figures as they are now. */
    49	    public Rollup take(String sheetId) {
    50	        var today = sheets.today(sheetId);
    51	        var floor = settings.floor(sheetId);
    52	        BigDecimal cap = settings.cap(sheetId);
    53	        LateCharge late = LateCharge.of(sheetId, settings, sheets, claims, people);
    54	        List<Claim> all = claims.list(sheetId);
    55	        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
    56	        BigDecimal claimedTotal = new BigDecimal("0.00");
    57	        List<BigDecimal> dues = new ArrayList<>();
    58	        List<BigDecimal> overdues = new ArrayList<>();
    59	        for (Person p : people.list(sheetId)) {
    60	            List<Claim> theirs = all.stream().filter(c -> c.personId() == p.id()).toList();
    61	            // claimed: the amounts of their claims that count toward claimed (a held one does), leaving out corrections of another claim
    62	            BigDecimal claimed = theirs.stream()
    63	                    .filter(c -> Dues.countsClaimed(c, p.retiredFrom(), today) && c.corrects() == null)
    64	                    .map(Claim::amount).reduce(new BigDecimal("0.00"), BigDecimal::add);
    65	            BigDecimal due = Dues.capped(
    66	                    Dues.total(sheetId, theirs, p.grades(), p.holds(), p.retiredFrom(), today, rates, floor, late), cap);
    67	            // overdue-total: the dues (as shown, late charge included) of their overdue claims that count, skipping n/a
    68	            BigDecimal overdue = theirs.stream()
    69	                    .filter(c -> Dues.counts(c, p.holds(), p.retiredFrom(), today) && late.overdue(c))
    70	                    .map(c -> Dues.shown(c, p.grades(), rates, floor, late)).filter(Objects::nonNull)
    71	                    .reduce(new BigDecimal("0.00"), BigDecimal::add);
    72	            claimedTotal = claimedTotal.add(claimed);
    73	            overdues.add(overdue);
    74	            if (due != null) {
    75	                dues.add(due);
    76	            }
    77	            figures.put(p.id(), new Rollup.Figures(p.name(), shown(claimed), due != null ? shown(due) : "n/a",
    78	                    shown(overdue)));
    79	        }
    80	        return new Rollup(figures, shown(claimedTotal), shown(trimmed(dues)), shown(trimmed(overdues)));
    81	    }
    82	
    83	    /** Record how the sheet's figures moved since `before`, as a change made by `user`. */
    84	    public void record(String sheetId, String user, Rollup before) {
    85	        Rollup after = take(sheetId);
    86	        for (var e : after.people().entrySet()) {
    87	            Rollup.Figures was = before.people().get(e.getKey());
    88	            Rollup.Figures now = e.getValue();
    89	            if (was == null || !Objects.equals(was.claimed(), now.claimed())
    90	                    || !Objects.equals(was.dueTotal(), now.dueTotal())
    91	                    || !Objects.equals(was.overdueTotal(), now.overdueTotal())) {
    92	                audit.record("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
    93	                        + " claimed=" + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
    94	            }
    95	        }
    96	        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
    97	                || !before.overdueTotal().equals(after.overdueTotal())) {
    98	            audit.record("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
    99	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
   100	        }
   101	        BigDecimal threshold = settings.alertThreshold(sheetId);
   102	        if (threshold != null) {
   103	            for (var e : after.people().entrySet()) {
   104	                Rollup.Figures was = before.people().get(e.getKey());
   105	                Rollup.Figures now = e.getValue();
   106	                if (!above(was != null ? was.dueTotal() : null, threshold) && above(now.dueTotal(), threshold)) {
   107	                    audit.record("ALERT sheet=" + sheetId + " by=" + user + " name=" + now.name()
   108	                            + " due-total=" + now.dueTotal());
   109	                }
   110	            }
   111	        }
   112	    }
   113	
   114	    /** Whether a due-total as shown (n/a or none: no due-total) is above the threshold. */
   115	    private static boolean above(String dueTotal, BigDecimal threshold) {
   116	        return dueTotal != null && !"n/a".equals(dueTotal) && new BigDecimal(dueTotal).compareTo(threshold) > 0;
   117	    }
   118	
   119	    /** Per-person figures added up, leaving out the single highest and the single lowest when there are three or more. */
   120	    private static BigDecimal trimmed(List<BigDecimal> figures) {
   121	        List<BigDecimal> sorted = figures.stream().sorted().toList();
   122	        if (sorted.size() >= 3) {
   123	            sorted = sorted.subList(1, sorted.size() - 1);
   124	        }
   125	        return sorted.stream().reduce(new BigDecimal("0.00"), BigDecimal::add);
   126	    }
   127	
   128	    private static String shown(BigDecimal value) {
   129	        return value.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
   130	    }
   131	}
