    14	/** Cancel the person's last statement: only a steward may, and only of a person with a statement. The claims it
    15	 *  bound become live again (a figure an earlier statement bound them to is not restored), there is one statement
    16	 *  fewer, and the row shows the one before it (or none). Publishes the cancelled statement (its due-total; the
    17	 *  claims it bound). */
    18	public class CancelStatement {
    19	    public void cancel(@Val StatementRequest request, @Val Person loaded, PersonRepository people,
    20	            ClaimRepository claims, RoleRepository roles, Out<Statement> statement, Out<PersonResponse> saved)
    21	            throws InvalidPersonException {
    22	        if (!Role.STEWARD.equals(roles.of(loaded.sheetId(), request.user()))) {
    23	            throw new InvalidPersonException("Only a steward may cancel a statement.");
    24	        }
    25	        people.lock(loaded);
    26	        Person person = people.find(loaded.sheetId(), loaded.id());
    27	        if (person.statementCount() == 0) {
    28	            throw new InvalidPersonException(person.name() + " has no statement to cancel.");
    29	        }
    30	        int bound = 0;
    31	        for (Claim c : claims.listForPerson(person.sheetId(), person.id())) {
    32	            if (c.stated()) {
    33	                bound++;
    34	                claims.state(c, false, null);
    35	            }
    36	        }
    37	        people.unstated(person);
    38	        statement.set(new Statement(person.sheetId(), person.name(), person.statedTotal(), bound, null));
    39	        saved.set(PersonResponse.from(people.find(person.sheetId(), person.id())));
    40	    }
