     6	/** A sheet's rate for a grade: a percent with two decimals, in force from its from-date (null: from the
     7	 *  beginning of time) through its to-date (null: with no end); its version is how many have been set for the grade
     8	 *  from that from-date, this the newest. A forward-only rate (saved with a from-date on or after the sheet's today)
     9	 *  carries the highest claim id when it was saved (after; null: it applies to every claim): it applies only to claims
    10	 *  added after it. */
    11	public record Rate(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to, int version, Long after) {
    12	
    13	    /** Whether this rate reaches the claim: it is not forward-only, or the claim was added after it was saved (a claim
    14	     *  id of 0 or less: no claim in particular, or one not yet added, which every rate reaches). */
    15	    public boolean reaches(long claimId) {
    16	        return after == null || claimId <= 0 || claimId > after;
    17	    }
    18	
    19	    /** Whether this rate could apply on the date: it has no from-date, or its from-date is on or before it. */
    20	    public boolean appliesOn(LocalDate date) {
    21	        return from == null || !from.isAfter(date);
    22	    }
    23	
    24	    /** Whether the date is after this rate's to-date: the rate has ended by then. */
    25	    public boolean endedBy(LocalDate date) {
    26	        return to != null && to.isBefore(date);
    27	    }
    28	}
