    10	/** The sheet's rates a figure is worked out with: as they are now (RateRepository), or as they stood at the end of a
    11	 *  day (RateRepository.asOf). */
    12	@FunctionalInterface
    13	public interface Rates {
    14	
    15	    /** The grade's rate in force on the date for the claim (see Rate.reaches; 0: without regard to any claim); empty
    16	     *  when none applies. */
    17	    Optional<Rate> on(String sheetId, String grade, LocalDate date, long claimId);
    18	
    19	    /** The grade's rate in force on the date, without regard to any claim; empty when none applies. */
    20	    default Optional<Rate> on(String sheetId, String grade, LocalDate date) {
    21	        return on(sheetId, grade, date, 0);
    22	    }
    23	
    24	    /** Of every version of a sheet's rates (oldest first), the ones in force for the claim: for each grade and
    25	     *  from-date, the newest version that reaches it (see Rate.reaches; 0: the newest of all), each grade's earliest
    26	     *  first. */
    27	    static List<Rate> forClaim(List<Rate> versions, long claimId) {
    28	        Map<String, Rate> byGradeFrom = new LinkedHashMap<>();
    29	        for (Rate r : versions) {
    30	            if (r.reaches(claimId)) {
    31	                byGradeFrom.put(r.grade() + "|" + r.from(), r);
    32	            }
    33	        }
    34	        return byGradeFrom.values().stream().sorted(Comparator.comparing(Rate::grade)
    35	                .thenComparing(Rate::from, Comparator.nullsFirst(Comparator.naturalOrder()))).toList();
    36	    }
    37	
    38	    /** Of the rates, the grade's in force on the date: the one whose from-date is the latest on or before it (no
    39	     *  from-date counting as the beginning of time); empty when none applies, or that one's to-date is before the date. */
    40	    static Optional<Rate> on(List<Rate> rates, String grade, LocalDate date) {
    41	        return rates.stream().filter(r -> r.grade().equals(grade) && r.appliesOn(date))
    42	                .max(Comparator.comparing(Rate::from, Comparator.nullsFirst(Comparator.naturalOrder())))
    43	                .filter(r -> !r.endedBy(date));
    44	    }
    45	}
