     9	/** The rate form's rules and its RATE_SET line, shared by the form's set and the rate import: the grade is one of A, B
    10	 *  or C, the rate a percent 0.00 or more with up to two decimals, the from-date and to-date (each optional) real
    11	 *  yyyy-mm-dd dates, the to-date not before the from-date. */
    12	public final class RateRules {
    13	    private static final Set<String> GRADES = Set.of("A", "B", "C");
    14	
    15	    private RateRules() {
    16	    }
    17	
    18	    /** The rate set for the grade checked by the rate form's rules: refused when any fails. */
    19	    public static RateInput check(String user, String grade, RateRequest request) throws InvalidRateException {
    20	        String g = grade == null ? "" : grade.trim();
    21	        if (!GRADES.contains(g)) {
    22	            throw new InvalidRateException("The grade must be A, B or C.");
    23	        }
    24	        String rate = request.rate() == null ? "" : request.rate().trim();
    25	        if (!rate.matches("\\d{1,5}(\\.\\d{1,2})?")) {
    26	            throw new InvalidRateException("The rate must be a percent, 0.00 to 99999.99, with up to two decimals.");
    27	        }
    28	        String fromText = request.from() == null ? "" : request.from().trim();
    29	        LocalDate from = null;
    30	        if (!fromText.isEmpty()) {
    31	            try {
    32	                from = LocalDate.parse(fromText);
    33	            } catch (DateTimeParseException e) {
    34	                throw new InvalidRateException("The from-date must be a date, yyyy-mm-dd.");
    35	            }
    36	        }
    37	        String toText = request.to() == null ? "" : request.to().trim();
    38	        LocalDate to = null;
    39	        if (!toText.isEmpty()) {
    40	            try {
    41	                to = LocalDate.parse(toText);
    42	            } catch (DateTimeParseException e) {
    43	                throw new InvalidRateException("The to-date must be a date, yyyy-mm-dd.");
    44	            }
    45	            if (from != null && to.isBefore(from)) {
    46	                throw new InvalidRateException("The to-date must not be before the from-date.");
    47	            }
    48	        }
    49	        return new RateInput(user, g, new BigDecimal(rate).setScale(2), from, to);
    50	    }
    51	
    52	    /** The RATE_SET line for the stored rate, set by the input's user. */
    53	    public static void record(RateInput input, Rate rate, Audit audit) {
    54	        audit.record("RATE_SET sheet=" + rate.sheetId() + " by=" + input.user()
    55	                + " grade=" + rate.grade() + " rate=" + rate.pct().toPlainString()
    56	                + (rate.from() != null ? " from=" + rate.from() : "")
    57	                + (rate.to() != null ? " to=" + rate.to() : ""));
    58	    }
    59	}
