    15	/** Rates by sheet: per grade, at most one in force per from-date (and at most one with no from-date) — the newest of
    16	 *  the versions set for it, the older ones kept. A grade with no rate in
    17	 *  force on a date on a sheet takes its parent sheet's rate on that date, then the parent's parent's, up to
    18	 *  {@link #LEVELS} levels up; then, on a sheet that was cloned, the sheet it was cloned from and its parents, then
    19	 *  that sheet's source and its parents, and so on (see {@link #lineage}). */
    20	@Repository
    21	public class RateRepository implements Rates {
    22	
    23	    private static final RowMapper<Rate> ROW = (rs, i) -> new Rate(rs.getString("sheet_id"),
    24	            rs.getString("grade"), rs.getBigDecimal("pct"), rs.getObject("from_date", LocalDate.class),
    25	            rs.getObject("to_date", LocalDate.class), version(rs.getObject("version", Integer.class)),
    26	            rs.getObject("after_claim", Long.class));
    27	
    28	    private static int version(Integer version) {
    29	        return version != null ? version : 1;
    30	    }
    31	
    32	    /** How many levels of parent sheets a rate is looked up through. */
    33	    public static final int LEVELS = 3;
    34	
    35	    private final JdbcTemplate jdbc;
    36	
    37	    public RateRepository(JdbcTemplate jdbc) {
    38	        this.jdbc = jdbc;
    39	    }
    40	
    41	    /** The sheet's rates in force by grade (each grade and from-date's newest version), each grade's earliest first
    42	     *  (the one with no from-date before all). */
    43	    public List<Rate> list(String sheetId) {
    44	        return jdbc.query("SELECT * FROM rate r WHERE sheet_id = ? AND version = (SELECT MAX(v.version) FROM rate v "
    45	                + "WHERE v.sheet_id = r.sheet_id AND v.grade = r.grade AND v.from_date IS NOT DISTINCT FROM r.from_date) "
    46	                + "ORDER BY grade, from_date NULLS FIRST", ROW, sheetId);
    47	    }
    48	
    49	    /** Every version of the sheet's rates, each grade and from-date's oldest first. */
    50	    public List<Rate> versions(String sheetId) {
    51	        return jdbc.query("SELECT * FROM rate WHERE sheet_id = ? ORDER BY grade, from_date NULLS FIRST, version", ROW,
    52	                sheetId);
    53	    }
    54	
    55	    /** The grade's rate in force on the date for the claim (0: without regard to any claim): of the versions that
    56	     *  reach it (see Rate.reaches), the one whose from-date is the latest on or before it (no from-date counting as
    57	     *  the beginning of time); empty when none applies, or that one's to-date is before the date; then the same of
    58	     *  the sheet's lineage, nearest first. */
    59	    @Override
    60	    public Optional<Rate> on(String sheetId, String grade, LocalDate date, long claimId) {
    61	        Optional<Rate> rate = Rates.on(Rates.forClaim(versions(sheetId), claimId), grade, date);
    62	        for (String parent : lineage(sheetId)) {
    63	            if (rate.isPresent()) {
    64	                break;
    65	            }
    66	            rate = Rates.on(Rates.forClaim(versions(parent), claimId), grade, date);
    67	        }
    68	        return rate;
    69	    }
    70	
    71	    /** The sheet's rates as they stood at the end of the day: each set from a from-date replaces the one set before
    72	     *  it for the grade from that same date; with its lineage's rates as they stood then, nearest first. */
    73	    public Rates asOf(String sheetId, LocalDate end) {
    74	        List<List<Rate>> levels = new ArrayList<>();
    75	        levels.add(versionsAsOf(sheetId, end));
    76	        for (String parent : lineage(sheetId)) {
    77	            levels.add(versionsAsOf(parent, end));
    78	        }
    79	        return (sheet, grade, date, claimId) -> levels.stream()
    80	                .map(versions -> Rates.on(Rates.forClaim(versions, claimId), grade, date))
    81	                .flatMap(Optional::stream).findFirst();
    82	    }
    83	
    84	    /** The sheet's parent sheets, nearest first, up to LEVELS of them (fewer when the chain ends sooner). */
    85	    public List<String> parents(String sheetId) {
    86	        List<String> parents = new ArrayList<>();
    87	        String at = sheetId;
    88	        while (parents.size() < LEVELS) {
    89	            at = parent(at);
    90	            if (at == null || at.equals(sheetId) || parents.contains(at)) {
    91	                break;
    92	            }
    93	            parents.add(at);
    94	        }
    95	        return parents;
    96	    }
    97	
    98	    /** The sheets a grade with no rate of the sheet's own takes one from, nearest first: its parents (see parents),
    99	     *  then, when it was cloned, the sheet it was cloned from followed by that sheet's own lineage; each sheet at most
   100	     *  once, never the sheet itself. */
   101	    public List<String> lineage(String sheetId) {
   102	        List<String> lineage = new ArrayList<>();
   103	        Set<String> seen = new HashSet<>();
   104	        seen.add(sheetId);
   105	        String at = sheetId;
   106	        while (at != null) {
   107	            for (String parent : parents(at)) {
   108	                if (seen.add(parent)) {
   109	                    lineage.add(parent);
   110	                }
   111	            }
   112	            at = clonedFrom(at);
   113	            if (at == null || !seen.add(at)) {
   114	                break;
   115	            }
   116	            lineage.add(at);
   117	        }
   118	        return lineage;
   119	    }
   120	
   121	    private String clonedFrom(String sheetId) {
   122	        return jdbc.query("SELECT cloned_from FROM sheet WHERE id = ?", rs -> rs.next() ? rs.getString(1) : null,
   123	                sheetId);
   124	    }
   125	
   126	    private String parent(String sheetId) {
   127	        return jdbc.query("SELECT parent FROM sheet WHERE id = ?", rs -> rs.next() ? rs.getString(1) : null, sheetId);
   128	    }
   129	
   130	    /** The sheet's rates as they stood at the end of the day, by grade, each grade's earliest first (see asOf). */
   131	    public List<Rate> listAsOf(String sheetId, LocalDate end) {
   132	        return Rates.forClaim(versionsAsOf(sheetId, end), 0);
   133	    }
   134	
   135	    /** Every rate set on the sheet by the end of the day, in the order set (each set from a from-date the next
   136	     *  version of the one set before it for the grade from that same date). */
   137	    public List<Rate> versionsAsOf(String sheetId, LocalDate end) {
   138	        return jdbc.query("SELECT * FROM rate_log WHERE sheet_id = ? AND (made_on IS NULL OR made_on <= ?) ORDER BY id",
   139	                ROW, sheetId, end);
   140	    }
   141	
   142	    /** Set the grade's rate from the from-date (null: from the beginning of time) through the to-date (null:
   143	     *  with no end) as the next version of the grade's rate from that same date, keeping any it replaces as an older
   144	     *  version. One with a from-date on or after the sheet's today is forward-only: it reaches only claims added after
   145	     *  it (see Rate.reaches). */
   146	    public Rate set(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to) {
   147	        Date fromDate = from != null ? Date.valueOf(from) : null;
   148	        Date toDate = to != null ? Date.valueOf(to) : null;
   149	        LocalDate today = jdbc.query("SELECT today FROM sheet WHERE id = ?",
   150	                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
   151	        Long after = from != null && today != null && !from.isBefore(today)
   152	                ? jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) FROM claim", Long.class)
   153	                : null;
   154	        Integer latest = jdbc.queryForObject("SELECT MAX(version) FROM rate WHERE sheet_id = ? AND grade = ? "
   155	                + "AND from_date IS NOT DISTINCT FROM ?", Integer.class, sheetId, grade, fromDate);
   156	        int version = latest != null ? latest + 1 : 1;
   157	        jdbc.update("INSERT INTO rate (sheet_id, grade, pct, from_date, to_date, version, after_claim) "
   158	                + "VALUES (?, ?, ?, ?, ?, ?, ?)", sheetId, grade, pct, fromDate, toDate, version, after);
   159	        jdbc.update("INSERT INTO rate_log (sheet_id, grade, pct, from_date, to_date, made_on, version, after_claim) "
   160	                + "VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?), ?, ?)", sheetId, grade, pct, fromDate,
   161	                toDate, sheetId, version, after);
   162	        return new Rate(sheetId, grade, pct, from, to, version, after);
   163	    }
   164	}
