     8	/** Bind the body and refuse it before anything is read or written. Each non-blank line is grade,rate,from,to — the
     9	 *  from-date and to-date may be absent or blank — and must pass exactly the rate form's rules. A paste with no lines is
    10	 *  refused. A refusal names the first line that fails. */
    11	public class ValidateRateImport {
    12	    public void validate(@RequestBody RateImportRequest request, Out<RateImportInput> body)
    13	            throws InvalidRateException {
    14	        if (request == null || request.user() == null || request.user().isBlank()) {
    15	            throw new InvalidRateException("Sign in before changing rates.");
    16	        }
    17	        String user = request.user().trim();
    18	        String[] rows = (request.text() == null ? "" : request.text()).split("\\r?\\n|\\r", -1);
    19	        List<RateInput> rates = new ArrayList<>();
    20	        for (int i = 0; i < rows.length; i++) {
    21	            if (rows[i].isBlank()) {
    22	                continue;
    23	            }
    24	            String[] fields = rows[i].split(",", -1);
    25	            try {
    26	                if (fields.length > 4) {
    27	                    throw new InvalidRateException("A line is grade,rate,from,to.");
    28	                }
    29	                rates.add(RateRules.check(user, fields[0], new RateRequest(user, fields.length > 1 ? fields[1] : "",
    30	                        fields.length > 2 ? fields[2] : "", fields.length > 3 ? fields[3] : "")));
    31	            } catch (InvalidRateException e) {
    32	                throw new InvalidRateException("Line " + (i + 1) + ": " + e.getMessage());
    33	            }
    34	        }
    35	        if (rates.isEmpty()) {
    36	            throw new InvalidRateException("Paste at least one line: grade,rate,from,to.");
    37	        }
