    13	/** The sheet's rate for each grade that has one (as they stood at the end of the as-of date, when one is given),
    14	 *  then its lineage's rates (its parents', then those of the sheet it was cloned from and so on), nearest first, each marked with its level and carrying its older versions. */
    15	public class RespondWithRates {
    16	    public void respond(@PathVariable("sheetId") String sheetId,
    17	            @RequestParam(name = "asOf", required = false) String asOf, RateRepository repository,
    18	            ObjectResponse<List<RateResponse>> response) {
    19	        String id = sheetId.trim();
    20	        LocalDate end = AsOf.parse(asOf);
    21	        List<String> sheets = new ArrayList<>();
    22	        sheets.add(id);
    23	        sheets.addAll(repository.lineage(id));
    24	        List<RateResponse> shown = new ArrayList<>();
    25	        for (int level = 0; level < sheets.size(); level++) {
    26	            List<Rate> versions = end != null ? repository.versionsAsOf(sheets.get(level), end)
    27	                    : repository.versions(sheets.get(level));
    28	            for (Rate r : Rates.forClaim(versions, 0)) {
    29	                List<Rate> older = new ArrayList<>(versions.stream().filter(v -> v != r && v.grade().equals(r.grade())
    30	                        && Objects.equals(v.from(), r.from())).toList());
    31	                Collections.reverse(older);
    32	                shown.add(RateResponse.from(r, level, older));
    33	            }
    34	        }
    35	        response.send(shown);
    36	    }
    37	}
