5	    14	 *  OPEN claim with the split-off amount, the same person, date and note, the next number, opened by the user, its
6	    15	 *  terms fixed now from the terms in force on the sheet's today (as a new claim's is) and the claim's number as its
7	    16	 *  split-from is stored (a late entry when that due-by is inside a soft-closed period), its OPEN line starting its status log. A split another user's change got to first is
8	    17	 *  refused. */
9	    18	public class SaveSplit {
10	    19	    public void save(@Val SplitInput input, @Val Claim loaded, SheetRepository sheets, SettingRepository settings,
11	    20	            HolidayRepository holidays, PersonRepository people, PeriodRepository periods, ClaimRepository repository, ClaimLogRepository log, Out<Split> split,
12	    21	            Out<ClaimResponse> saved) throws ClaimStatusNotAllowedException, InvalidClaimException {
13	    22	        if (loaded.status() != ClaimStatus.OPEN) {
14	    23	            throw new ClaimStatusNotAllowedException("A " + loaded.status()
15	    24	                    + " claim cannot be split; only an OPEN one can.");
16	    25	        }
17	    26	        var today = sheets.today(loaded.sheetId());
18	    27	        if (loaded.deferredOn(today)) {
19	    28	            throw new ClaimStatusNotAllowedException("This claim is deferred until " + loaded.deferredUntil()
20	    29	                    + "; it cannot be split.");
21	    30	        }
22	    31	        if (input.amount().compareTo(loaded.amount()) >= 0) {
23	    32	            throw new InvalidClaimException("The amount to split off must be less than the claim's "
24	    33	                    + loaded.amount().toPlainString() + ".");
25	    34	        }
