30	/** Whether one of the person's holds covers the date (yyyy-mm-dd). */
31	export function heldOn(person: Person | undefined, date: string): boolean {
32	  return (person?.holds ?? []).some((h) => (h.from === null || h.from <= date) && (h.to === null || date <= h.to));
33	}
