35	/** Whether the person's retirement date is reached on the sheet's today (yyyy-mm-dd; '' while loading: not reached):
36	 *  from then their OPEN and PENDING claims not bound by a statement count in no live total. */
37	export function retiredOn(person: Person | undefined, today: string): boolean {
