44	/** The person's grade in force on a date (yyyy-mm-dd): the one whose from-date is the latest on or before it,
45	 *  a grade with no from-date applying from the beginning of time; '' when none applies. */
46	export function gradeOn(person: Person | undefined, date: string): string {
47	  let found: Grade | undefined;
48	  for (const g of person?.grades ?? []) {
49	    if (g.from !== null && g.from > date) continue;
50	    if (!found || (found.from ?? '') <= (g.from ?? '')) found = g;
51	  }
52	  return found?.grade ?? '';
