1	import { useEffect, useRef } from 'react';
2	import type { ReactNode } from 'react';
3	import { formatFigure } from './locale';
4	import type { Locale } from './locale';
5	
6	// Text inside these is never a figure shown in a cell (option labels are matched by tests and people as typed).
7	const SKIP = new Set(['OPTION', 'TEXTAREA', 'SCRIPT', 'STYLE']);
8	
9	/** Shows every figure inside it in the user's locale: any element whose whole text is a number with two decimals
10	 *  (an amount, due, total, rate, share, cut...) is shown as 1.234,56 under de. Done on the screen's text, after
11	 *  React renders it, so each feature keeps rendering the plain figure it reads from the server (as exports and
12	 *  audit lines carry it); when the locale goes back to en every figure changed here is put back. */
13	export function LocaleFigures({ locale, children }: { locale: Locale; children: ReactNode }) {
14	  const ref = useRef<HTMLDivElement>(null);
15	
16	  useEffect(() => {
17	    const root = ref.current;
18	    if (!root || locale === 'en') return;
19	    // The text React rendered, for each text node shown differently here — to put back.
20	    const changed = new Map<Text, { plain: string; shown: string }>();
21	
22	    const visit = (node: Text) => {
23	      const parent = node.parentElement;
24	      if (!parent || SKIP.has(parent.tagName)) return;
25	      const text = node.nodeValue ?? '';
26	      if ((parent.textContent ?? '').trim() !== text.trim()) return;
27	      const shown = formatFigure(text, locale);
28	      if (shown === text) return;
29	      changed.set(node, { plain: text, shown });
30	      node.nodeValue = shown;
31	    };
32	    const walk = (node: Node) => {
33	      if (node.nodeType === Node.TEXT_NODE) {
34	        visit(node as Text);
35	        return;
36	      }
37	      const texts = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);
38	      for (let t = texts.nextNode(); t; t = texts.nextNode()) visit(t as Text);
39	    };
40	
41	    walk(root);
42	    const observer = new MutationObserver((records) => {
43	      for (const r of records) {
44	        if (r.type === 'characterData') walk(r.target);
45	        else r.addedNodes.forEach(walk);
46	      }
47	    });
48	    observer.observe(root, { subtree: true, childList: true, characterData: true });
49	    return () => {
50	      observer.disconnect();
51	      for (const [node, { plain, shown }] of changed) {
52	        if (node.isConnected && node.nodeValue === shown) node.nodeValue = plain;
53	      }
54	    };
55	  }, [locale]);
56	
57	  return (
58	    <div ref={ref} style={{ display: 'contents' }}>
59	      {children}
60	    </div>
61	  );
62	}
