14	/** Every claim status claims are counted by, in life order, each shown even when no claim has it (not DELETED: a
15	 *  deleted claim counts nowhere). */
16	export const STATUSES: readonly ClaimStatus[] = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'REVIEW'];
17	
18	/** A person's claim: the amount with two decimals, the date (yyyy-mm-dd), a note (may be empty), its status,
19	 *  its number (sheet-wide digits as given before fiscal-year numbering, FY<yyyy>-<n> within the tree's fiscal year, or <period name>-<n> / X-<n> when numbered within its period; null while a draft; a voided claim keeps the one it had) and, the due fixed when it was settled
20	 *  (null when not settled, or its grade had no rate then: its due follows the rates), and who opened it
21	 *  (null while a draft), whether its person's last statement bound it (it counted then) and the figure it bound
22	 *  it to (null when not bound, or n/a then: its due stays live), and for a correction (a negative amount) the
23	 *  number of the SETTLED claim of the same person it corrects (null otherwise), and its due-by (yyyy-mm-dd): the
24	 *  terms-th business day after its date when it was created, with the terms fixed then (its person's own, else their
25	 *  grade's in force on that date, else the sheet's), past Saturdays, Sundays and the sheet's holidays now, and its
26	 *  status log: one line per status it has had, oldest first, as <STATUS> by <user> on <date> due=<due>, and the date
27	 *  it is deferred until (yyyy-mm-dd; null when never deferred) and whether it is deferred on the sheet's today (an
28	 *  OPEN claim deferred until after it: it counts in no total, is not overdue and cannot be settled), and its proofs
29	 *  count (raised one at a time, not on a SETTLED or VOID claim; one whose due is above the proof threshold in force
30	 *  on its date cannot be settled or approved while it is 0 — the server refuses it), and the number
31	 *  of the claim it was split from (null when it was not split off one), and the last sheet-today it was reminded
32	 *  (yyyy-mm-dd; null when never: only an OPEN or PENDING claim, once per sheet-today), and its external reference
33	 *  (null when none: unique on the sheet without regard to case — the server refuses a repeat), and its tags (trimmed,
34	 *  lower-cased, without repeats, sorted; empty when none), and its comments, oldest first, as <user> on <date>: <text>
35	 *  (the date being the sheet's today when it was written), and the number of the settle batch that settled it (null when
36	 *  none did: it was settled one at a time, or is not settled), and its lines, in the order added, as
37	 *  <label> <qty> x <unit> (only a DRAFT takes a line; a claim with lines has their total as its amount — the server
38	 *  refuses an edit typing another), and its review day (yyyy-mm-dd): the sheet's today when it went to REVIEW (null
39	 *  when it never did), and whether a steward waived its late charge (only an OPEN or PENDING claim, once: it then
40	 *  bears no late charge, overdue or not), and how many of its proofs are of each kind (receipt, photo: a proof added
41	 *  with no kind chosen is a receipt; while the sheet lists proof kinds, one above the proof threshold needs a proof of
42	 *  each listed kind before it can be settled or approved — the server refuses it), and whether it is held (only an
43	 *  OPEN or PENDING claim is held or released: a held claim is left out of the live totals as a held person's are). */
44	export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
45	  number: string | null; settledDue: string | null; openedBy: string | null; stated: boolean;
46	  statedDue: string | null; corrects: string | null; dueBy: string; log: string[];
47	  deferredUntil: string | null; deferred: boolean; proofs: number; splitFrom: string | null;
48	  lateEntry: boolean; reminded: string | null; ref: string | null; tags: string[];
49	  comments: string[]; batch: number | null; lines: string[]; reviewOn?: string | null;
50	  waived: boolean; proofKinds?: Record<string, number>; held: boolean };
51	
52	/** The kinds a proof can be, in the order shown: a proof added with none chosen is a receipt. */
53	export const PROOF_KINDS = ['receipt', 'photo'] as const;
54	
55	/** Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED ones do, except
56	 *  one deferred on the sheet's today. */
57	export function counts(c: Claim): boolean {
58	  return (c.status === 'OPEN' || c.status === 'PENDING' || c.status === 'SETTLED') && !c.deferred;
59	}
60	
61	/** Whether a claim is still to be settled: OPEN or PENDING (it goes overdue). */
62	export function unsettled(c: Claim): boolean {
63	  return c.status === 'OPEN' || c.status === 'PENDING';
64	}
65	
66	/** Whether a claim is left out of the live totals by its person (among those given by id): an OPEN or PENDING one
67	 *  once their retirement date is reached on the sheet's today (yyyy-mm-dd), not bound by a statement. A hold (the
68	 *  claim's own or its person's) leaves nothing out of the totals; it only takes the person out of the pools' cuts. */
69	function leftOut(c: Claim, byId: Map<number, Person>, today: string): boolean {
70	  if (c.stated) return false;
71	  const person = byId.get(c.personId);
72	  return unsettled(c) && retiredOn(person, today);
73	}
74	
75	/** The claims that count in the live totals among these on the sheet's today (yyyy-mm-dd): those that count, except
76	 *  those their person (among the people given) leaves out (see leftOut); their other claims still count. */
77	export function live(claims: Claim[], people: Person[], today: string): Claim[] {
78	  const byId = new Map(people.map((p) => [p.id, p]));
79	  return claims.filter((c) => counts(c) && !leftOut(c, byId, today));
80	}
81	
82	/** The claims that count toward claimed among these on the sheet's today (yyyy-mm-dd): as live. */
83	export function claimedLive(claims: Claim[], people: Person[], today: string): Claim[] {
84	  const byId = new Map(people.map((p) => [p.id, p]));
85	  return claims.filter((c) => counts(c) && !(!c.stated && unsettled(c) && retiredOn(byId.get(c.personId), today)));
86	}
87	
88	/** Whether a person is active on the sheet's today (yyyy-mm-dd; '' while loading: not active): they have an OPEN or
89	 *  PENDING claim that counts in the live totals (see live) dated within the 30 days up to and including it. */
90	export function active(person: Person, claims: Claim[], today: string): boolean {
91	  if (today === '') return false;
92	  const since = new Date(Date.parse(`${today}T00:00:00Z`) - 29 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
93	  return live(claims.filter((c) => c.personId === person.id), [person], today)
94	    .some((c) => unsettled(c) && c.date >= since && c.date <= today);
95	}
96	
97	/** A claim's status at the end of the day given (yyyy-mm-dd), as its status log records it: the last status given on
98	 *  or before that day (one given while the sheet had no today counts as given by then); null when every status was
99	 *  given after it (it was added later). A claim with no log has its status now. */
100	export function statusAt(c: Claim, day: string): ClaimStatus | null {
101	  if (c.log.length === 0) return c.status;
102	  let status: ClaimStatus | null = null;
103	  for (const line of c.log) {
104	    const m = /^(\S+) by .* on (\S*) due=\S+$/.exec(line);
105	    if (m && (m[2] === '' || m[2] <= day)) status = m[1] as ClaimStatus;
106	  }
107	  return status;
108	}
109	
110	/** The claims that count in a period's due-totals among these: those whose status at the end of the day given (see
111	 *  statusAt) is OPEN, PENDING or SETTLED, left out as live leaves them out on the sheet's today (yyyy-mm-dd):
112	 *  deferred, or left out by their person (among the people given; see leftOut). */
113	export function countedAt(claims: Claim[], people: Person[], day: string, today: string): Claim[] {
114	  const byId = new Map(people.map((p) => [p.id, p]));
115	  return claims.filter((c) => {
116	    const at = statusAt(c, day);
117	    return (at === 'OPEN' || at === 'PENDING' || at === 'SETTLED') && !c.deferred && !leftOut(c, byId, today);
118	  });
119	}
120	
121	/** A claim's due-by (yyyy-mm-dd), as the server works it out in business days. */
122	export function dueBy(claim: Claim): string {
123	  return claim.dueBy;
124	}
125	
126	/** The day (yyyy-mm-dd) a claim's late charge counts from: its due-by plus its grace (days; see Late). */
127	export function lateFrom(claim: Claim, grace = 0): string {
128	  if (grace === 0) return dueBy(claim);
129	  return new Date(Date.parse(`${dueBy(claim)}T00:00:00Z`) + grace * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
130	}
131	
132	/** Whether a claim is overdue: it is OPEN or PENDING, not deferred, and its due-by plus its grace (days) is before
133	 *  the sheet's today. */
134	export function overdue(claim: Claim, today: string, grace = 0): boolean {
135	  return unsettled(claim) && !claim.deferred && today !== '' && lateFrom(claim, grace) < today;
136	}
137	
138	/** Whether a claim is review-late on the sheet's today (yyyy-mm-dd; '' while loading: not late) under the sheet's
139	 *  review SLA (days; '' when none: never late): it is REVIEW and its review day plus the SLA days is before today. */
140	export function reviewLate(claim: Claim, today: string, sla: string): boolean {
141	  if (claim.status !== 'REVIEW' || !claim.reviewOn || today === '' || sla === '') return false;
142	  const due = new Date(Date.parse(`${claim.reviewOn}T00:00:00Z`) + Number(sla) * 24 * 60 * 60 * 1000)
143	    .toISOString().slice(0, 10);
144	  return due < today;
145	}
