147	export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;
148	
149	/** Every claim on the sheet, newest first. */
150	export const claimsQuery = (sheetId: string) => ({
151	  queryKey: claimsKey(sheetId),
152	  queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`),
153	});
154	
155	export function useClaims(sheetId: string) {
156	  return useQuery(claimsQuery(sheetId));
157	}
