159	/** Every tag ever used on the sheet's claims, sorted (kept even once no claim carries it). Under the claims' key, so
160	 *  it is fetched again whenever they are. */
161	export function useTagsUsed(sheetId: string) {
162	  return useQuery({
163	    queryKey: [...claimsKey(sheetId), 'tags'] as const,
164	    queryFn: () => getJson<string[]>(`/api/sheets/${encodeURIComponent(sheetId)}/tags`),
165	  });
166	}
167	
168	/** The number of the sheet's last settle batch (null when there has been none): each bulk settle that settled at
169	 *  least one claim (one left PENDING counts) is the next, numbered 1, 2, ... on the sheet. */
170	export function useLastBatch(sheetId: string) {
171	  return useQuery({
172	    queryKey: [...claimsKey(sheetId), 'settle-batch'] as const,
173	    queryFn: () => getJson<{ last: number | null }>(`/api/sheets/${encodeURIComponent(sheetId)}/settle-batch`),
174	  });
