176	
177	/** The id of the claim whose editor is open ('' when each person's claim form adds a new claim). */
178	export function useEditingClaim() {
179	  return useSearchParam('editClaim', asString);
180	}
181	
182	/** The amounts of the claims that count (OPEN, PENDING and SETTLED), leaving out those that correct another,
183	 *  added up exactly (in cents) and shown with two decimals: the claimed figure. */
184	export function sumAmounts(claims: Claim[]): string {
185	  const cents = claims.filter((c) => counts(c) && !c.corrects).reduce((total, c) => total + Math.round(Number(c.amount) * 100), 0);
186	  const abs = Math.abs(cents);
187	  return `${cents < 0 ? '-' : ''}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
188	}
