     7	/** Counting business days: every day that is not a Saturday, a Sunday or one of the sheet's holidays. */
     8	public final class BusinessDays {
     9	
    10	    private BusinessDays() {
    11	    }
    12	
    13	    /** The terms-th business day after the date, counting forward from the day after it (0 terms: the date itself). */
    14	    public static LocalDate after(LocalDate from, int terms, Set<LocalDate> holidays) {
    15	        LocalDate day = from;
    16	        for (int n = 0; n < terms;) {
    17	            day = day.plusDays(1);
    18	            if (isBusinessDay(day, holidays)) {
    19	                n++;
    20	            }
    21	        }
    22	        return day;
    23	    }
    24	
    25	    public static boolean isBusinessDay(LocalDate day, Set<LocalDate> holidays) {
    26	        return day.getDayOfWeek() != DayOfWeek.SATURDAY && day.getDayOfWeek() != DayOfWeek.SUNDAY
    27	                && !holidays.contains(day);
    28	    }
    29	}
