    10	/** Bind the body and refuse it before anything is read or written. Each non-blank line is name,period,amount with
    11	 *  an amount of two decimals, 0.00 or more. A paste with no lines is refused. A refusal names the first line that
    12	 *  fails. */
    13	public class ValidateOpeningImport {
    14	
    15	    private static final Pattern AMOUNT = Pattern.compile("\\d+\\.\\d{2}");
    16	
    17	    public void validate(@RequestBody OpeningImportRequest request, Out<OpeningImportInput> body)
    18	            throws InvalidOpeningException {
    19	        if (request == null || request.user() == null || request.user().isBlank()) {
    20	            throw new InvalidOpeningException("Sign in before pasting opening balances.");
    21	        }
    22	        String[] rows = (request.text() == null ? "" : request.text()).split("\\r?\\n|\\r", -1);
    23	        List<OpeningLine> lines = new ArrayList<>();
    24	        for (int i = 0; i < rows.length; i++) {
    25	            if (rows[i].isBlank()) {
    26	                continue;
    27	            }
    28	            String[] fields = rows[i].split(",", -1);
    29	            if (fields.length != 3 || fields[0].isBlank() || fields[1].isBlank()) {
    30	                throw new InvalidOpeningException("Line " + (i + 1) + ": a line is name,period,amount.");
    31	            }
    32	            String amount = fields[2].trim();
    33	            if (!AMOUNT.matcher(amount).matches()) {
    34	                throw new InvalidOpeningException("Line " + (i + 1) + ": the amount must have two decimals, 0.00 or more.");
    35	            }
    36	            lines.add(new OpeningLine(i + 1, fields[0].trim(), fields[1].trim(), new BigDecimal(amount)));
    37	        }
    38	        if (lines.isEmpty()) {
    39	            throw new InvalidOpeningException("Paste at least one line: name,period,amount.");
    40	        }
    41	        body.set(new OpeningImportInput(request.user().trim(), lines));
    42	    }
    43	}

