7	/** A grade's rate on the sheet: a percent with two decimals, in force from its from-date (yyyy-mm-dd, or
8	 *  null: from the beginning of time) through its to-date (null: with no end). A grade may have several, one
9	 *  per from-date; none when it has no rate. `level` is where it comes from: 0 the sheet's own, 1 its parent
10	 *  sheet's, 2 the parent's parent's, 3 the one above that; after them, on a cloned sheet, the sheet it was cloned from,
11	 *  its parents, its own source and so on. `version` is how many have been set for the grade from
12	 *  that from-date (this the newest, the one in force). A forward-only rate (saved with a from-date on or after the
13	 *  sheet's today) carries `after`, the highest claim id when it was saved: it reaches only claims added after it (a
14	 *  higher id); null or absent: every claim. `older` are the grade's older versions from that from-date, newest first:
15	 *  a claim the rate does not reach uses the newest of them that does. */
16	export type Rate = { grade: string; rate: string; from: string | null; to: string | null; level?: number; version?: number;
17	  after?: number | null; older?: OlderRate[] };
18	
19	/** An older version of a rate (see Rate). */
20	export type OlderRate = { rate: string; to: string | null; after?: number | null };
21	
22	/** Whether a rate (or an older version of one) reaches the claim (see Rate); every one does without a claim. */
23	function reaches(r: { after?: number | null }, claimId: number | undefined): boolean {
24	  return claimId === undefined || r.after == null || claimId > r.after;
25	}
26	
27	/** Of one sheet's rates, the ones in force for the claim: each grade and from-date's newest version that reaches it
28	 *  (see Rate); all of them as they are without a claim. */
29	function reaching(rates: Rate[], claimId: number | undefined): Rate[] {
30	  if (claimId === undefined) return rates;
31	  return rates.flatMap((r) => {
32	    if (reaches(r, claimId)) return [r];
33	    const older = (r.older ?? []).find((o) => reaches(o, claimId));
34	    return older ? [{ ...r, rate: older.rate, to: older.to, after: older.after }] : [];
35	  });
36	}
