38	/** Of the rates, the sheet's own (not its parents'). */
39	export function ownRates(rates: Rate[]): Rate[] {
40	  return rates.filter((r) => (r.level ?? 0) === 0);
41	}
42	
43	export const ratesKey = (sheetId: string) => ['sheet', sheetId, 'rates'] as const;
44	
45	/** The sheet's rates, every grade's every from-date, then its parents' (up to three levels up), then, on a clone,
46	 *  those of the sheet it was cloned from and its parents and source. */
47	export function useRates(sheetId: string) {
48	  return useQuery({
49	    queryKey: ratesKey(sheetId),
50	    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`),
51	  });
52	}
