54	/** A grade's rate in force on a date (yyyy-mm-dd), for the claim with the id when one is given (of the rates that
55	 *  reach it, see Rate): the one whose from-date is the latest on or before it, a rate with no from-date applying from
56	 *  the beginning of time; undefined when none applies, or that one's to-date is before the date. When the sheet's own
57	 *  has none, the nearest level's (parent, or a clone's source) that has one. */
58	export function rateOn(rates: Rate[], grade: string, date: string, claimId?: number): string | undefined {
59	  const levels = [...new Set(rates.map((r) => r.level ?? 0))].sort((a, b) => a - b);
60	  for (const level of levels) {
61	    const rate = levelRateOn(reaching(rates.filter((r) => (r.level ?? 0) === level), claimId), grade, date);
62	    if (rate !== undefined) return rate;
63	  }
64	  return undefined;
65	}
