67	/** Of one sheet's rates, the grade's in force on the date (see rateOn). */
68	function levelRateOn(rates: Rate[], grade: string, date: string): string | undefined {
69	  let found: Rate | undefined;
70	  for (const r of rates) {
71	    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
72	    if (!found || (found.from ?? '') < (r.from ?? '')) found = r;
73	  }
74	  if (found?.to != null && found.to < date) return undefined;
75	  return found?.rate;
76	}
