83	/** A two-decimal amount (may be negative) as whole cents, exactly. */
84	export function toCents(amount: string): bigint {
85	  const trimmed = amount.trim();
86	  const negative = trimmed.startsWith('-');
87	  const [whole, frac = ''] = (negative ? trimmed.slice(1) : trimmed).split('.');
88	  const cents = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
89	  return negative ? -cents : cents;
90	}
