102	/** Due on an amount: amount times rate, divided by 100, rounded to two decimals half to even, or half up (away
103	 *  from zero) when `halfUp` (exact, in integers); 'n/a' when there is no rate. */
104	export function dueOn(amount: string, rate: string | undefined, halfUp = false): string {
105	  if (rate === undefined) return 'n/a';
106	  const scaled = toCents(amount) * toCents(rate); // in 1/10000 of a cent
107	  const sign = scaled < 0n ? -1n : 1n;
108	  const abs = scaled * sign;
109	  let cents = abs / 10000n;
110	  const rest = abs % 10000n;
111	  if (rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n))) cents += 1n;
112	  return fromCents(cents * sign);
113	}
