182	 *  over their SETTLED claims that count, dated within the 90 days up to and including the sheet's today, added up,
183	 *  skipping n/a; 0.00 with none (or while today is loading). */
184	export function recentSettledSum(people: Person[], claims: Claim[], rates: Rate[], today: string, floor: DatedValue,
185	    late: Late): string {
186	  if (today === '') return '0.00';
187	  const since = new Date(Date.parse(`${today}T00:00:00Z`) - 89 * DAY_MS).toISOString().slice(0, 10);
188	  const byId = new Map(people.map((p) => [p.id, p]));
189	  return sumDue(claims
190	    .filter((c) => byId.has(c.personId) && c.status === 'SETTLED' && counts(c) && c.date >= since && c.date <= today)
191	    .map((c) => claimDue(c, rateOn(rates, gradeOn(byId.get(c.personId), c.date), c.date, c.id), floor, late)));
