194	/** 100.00 split equally among n patrons in the order named: each share 100.00 / n rounded to two decimals half to
195	 *  even, the first-named taking the remainder (100.00 minus the shares added up). */
196	export function patronShares(n: number): string[] {
197	  if (n <= 0) return [];
198	  const count = BigInt(n);
199	  let share = 10000n / count;
200	  const rest = 10000n % count;
201	  if (rest * 2n > count || (rest * 2n === count && share % 2n === 1n)) share += 1n;
202	  return Array.from({ length: n }, (_, i) => fromCents(i === 0 ? 10000n - share * (count - 1n) : share));
203	}
