205	/** Figures each weighted by a share: the sum of figure times share divided by 100, rounded half to even (exact, in
206	 *  integers); n/a figures are skipped. */
207	export function sharedSum(parts: { figure: string; share: string }[]): string {
208	  const scaled = parts.filter((p) => p.figure !== 'n/a')
209	    .reduce((total, p) => total + toCents(p.figure) * toCents(p.share), 0n); // in 1/10000 of a cent
210	  const sign = scaled < 0n ? -1n : 1n;
211	  const abs = scaled * sign;
212	  let cents = abs / 10000n;
213	  const rest = abs % 10000n;
214	  if (rest > 5000n || (rest === 5000n && cents % 2n === 1n)) cents += 1n;
215	  return fromCents(cents * sign);
216	}
