218	/** A sum of figures at most the cap ('' when none); 'n/a' is not capped. */
219	export function capped(sum: string, cap: string): string {
220	  return sum === 'n/a' || cap === '' || toCents(sum) <= toCents(cap) ? sum : fromCents(toCents(cap));
221	}
