223	/** How far a sum of figures is above the cap ('' when none); 0.00 when it is not above it, or n/a. */
224	export function excess(sum: string, cap: string): string {
225	  return sum === 'n/a' || cap === '' || toCents(sum) <= toCents(cap) ? '0.00' : fromCents(toCents(sum) - toCents(cap));
226	}
