228	/** Per-person figures added up, skipping n/a, leaving out the single highest and the single lowest figure when
229	 *  there are three or more. */
230	export function trimmedSum(figures: string[]): string {
231	  const sorted = figures.filter((f) => f !== 'n/a').map(toCents).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
232	  const kept = sorted.length >= 3 ? sorted.slice(1, -1) : sorted;
233	  return fromCents(kept.reduce((total, c) => total + c, 0n));
234	}
