257	/** What the late charge follows: the sheet's late percent by date (two decimals; a claim gains the one in force
258	 *  on each 30-day boundary past its due-by plus its grace) and its today; and each claim's grace in days (the grace in
259	 *  force on its date of its person's grade in force on that date; 0 when none: it is overdue past its due-by plus it); and
260	 *  how a claim's live figures round: the policy date (the policy-date setting, else the sheet's today; '' while
261	 *  loading) and the dates of the sheet's numbered claims (a correction rounds by the claim it corrects), and the
262	 *  rounding mode in force on a date (half-up or half-even; '' when none: the policy date rounds). */
263	export type Late = { pct: DatedValue; today: string; policy: string; numbered: Map<string, string>;
264	  grace: (claim: Claim) => number; rounding: DatedValue };
265	
266	/** Whether a claim's live figures round half up: by the rounding mode in force on its date (a correction: the date
267	 *  of the claim it corrects) when there is one; else when it is dated before the policy date; else they round half
268	 *  to even. */
269	export function roundsUp(claim: Claim, late: Late): boolean {
270	  const date = claim.corrects !== null ? late.numbered.get(claim.corrects) ?? claim.date : claim.date;
271	  const mode = late.rounding(date);
272	  if (mode !== '') return mode === 'half-up';
273	  return late.policy !== '' && date < late.policy;
274	}
275	
276	/** A claim's due: the one fixed when it was settled (its late charge frozen in), else the one its person's last
277	 *  statement bound it to as shown then (late charge and floor included; n/a included; an OPEN or PENDING one alike),
278	 *  else its floored figure (the greater of the sheet's floor in force on its date and its live figure on its amount at
279	 *  the rate) with the late charge worked out on that floored figure added. A correction (a negative amount) has no floor and no late charge. */
280	export function claimDue(claim: Claim, rate: string | undefined, floor: DatedValue, late: Late): string {
281	  if (claim.settledDue !== null) return claim.settledDue;
282	  if (claim.stated) return claim.statedDue ?? 'n/a';
283	  const correction = toCents(claim.amount) < 0n;
284	  const figure = dueOn(claim.amount, rate, roundsUp(claim, late));
285	  if (correction || figure === 'n/a') return figure;
286	  const base = floored(figure, floor(claim.date));
287	  return fromCents(toCents(base) + toCents(lateCharge(claim, base, late)));
288	}
289	
290	const DAY_MS = 24 * 60 * 60 * 1000;
291	
292	/** The late charge on a claim whose figure is `figure`: for each full 30 days the claim is overdue (past its due-by
293	 *  plus its grace, on the sheet's today), the late percent in force on that boundary date (its due-by plus its grace
294	 *  plus 30, 60, 90 ... days) of it plus the charges of the boundaries before (compounding), each
295	 *  rounded like the claim's due, the charges added up (a boundary whose percent is 0.00 adds nothing); 0.00 when not
296	 *  overdue, or a correction (a negative amount), or its late charge was waived. */
297	export function lateCharge(claim: Claim, figure: string, late: Late): string {
298	  const grace = late.grace(claim);
299	  if (!overdue(claim, late.today, grace) || toCents(claim.amount) < 0n || claim.waived) return '0.00';
300	  const from = Date.parse(`${lateFrom(claim, grace)}T00:00:00Z`);
301	  const days = Math.round((Date.parse(`${late.today}T00:00:00Z`) - from) / DAY_MS);
302	  let total = 0n;
303	  for (let n = 1; n <= Math.floor(days / 30); n++) {
304	    const pct = late.pct(new Date(from + n * 30 * DAY_MS).toISOString().slice(0, 10));
305	    if (toCents(pct) !== 0n) total += toCents(dueOn(fromCents(toCents(figure) + total), pct, roundsUp(claim, late)));
306	  }
307	  return fromCents(total);
308	}
309	
310	/** A due raised to the floor when below it; 'n/a' stays 'n/a'. */
311	export function floored(due: string, floor: string): string {
312	  return due === 'n/a' || toCents(due) >= toCents(floor) ? due : fromCents(toCents(floor));
313	}
