315	
316	/** A candidate rate's preview for a grade: of the OPEN and PENDING claims of people on the grade (the one in force on
317	 *  each claim's date), how many would show a different due (as shown on its row) if the candidate applied to the grade
318	 *  on every date, and the sum of the differences (new due minus current due; n/a counting as 0.00). A claim bound by a
319	 *  statement keeps its figure (see claimDue); a settled one is not counted. Nothing is saved. */
320	export function ratePreview(people: Person[], claims: Claim[], rates: Rate[], grade: string, pct: string,
321	    floor: DatedValue, late: Late): { count: number; diff: string } {
322	  const byId = new Map(people.map((p) => [p.id, p]));
323	  let count = 0;
324	  let diff = 0n;
325	  for (const c of claims) {
326	    const person = byId.get(c.personId);
327	    if (!person || (c.status !== 'OPEN' && c.status !== 'PENDING') || gradeOn(person, c.date) !== grade) continue;
328	    const was = claimDue(c, rateOn(rates, grade, c.date, c.id), floor, late);
329	    const now = claimDue(c, pct, floor, late);
330	    if (was === now) continue;
331	    count++;
332	    diff += (now === 'n/a' ? 0n : toCents(now)) - (was === 'n/a' ? 0n : toCents(was));
333	  }
334	  return { count, diff: fromCents(diff) };
335	}
