55	/** The value of a dated setting in force on a date: the one with the latest from-date on or before it, else the
56	 *  sheet's starting value. */
57	export function valueOn(values: Dated[] | undefined, start: string, date: string): string {
58	  let found: Dated | undefined;
59	  for (const v of values ?? []) {
60	    if (v.from <= date && (!found || found.from < v.from)) found = v;
61	  }
62	  return found ? found.value : start;
63	}
