136	/** What the late charge follows (see useLate), from a sheet's settings, its today, its claims and its people. */
137	export function lateOf(settings: Settings | undefined, today: string, claims: Claim[] | undefined,
138	    people: Person[] | undefined): Late {
139	  const numbered = new Map((claims ?? []).filter((c) => c.number !== null).map((c) => [c.number as string, c.date]));
140	  const dated = settings?.dated?.['late-pct'];
141	  const pct = (date: string) => valueOn(dated, DEFAULT_LATE_PCT, date);
142	  const byId = new Map((people ?? []).map((p) => [p.id, p]));
143	  const history = settings?.dated;
144	  const grace = (claim: Claim) => {
145	    const grade = gradeOn(byId.get(claim.personId), claim.date);
146	    if (grade === '') return 0;
147	    const days = valueOn(history?.[`grace-${grade}`], '', claim.date);
148	    return days === '' ? 0 : Number(days);
149	  };
150	  const rounding = (date: string) => valueOn(history?.rounding, '', date);
151	  return { pct, today, grace, policy: settings?.policyDate || today, numbered, rounding };
152	}
