154	/** What the late charge follows now: the late percent by date (a claim gains the one in force on its date) and the sheet's today, and each
155	 *  claim's grace (of its person's grade on its date, in force on that date; 0 while loading); and how claims round:
156	 *  the policy date in force (blank: the sheet's today) and the dates of the sheet's numbered claims. */
157	export function useLate(sheetId: string): Late {
158	  const settings = useSettings(sheetId).data;
159	  const today = useSheetToday(sheetId);
160	  const claims = useClaims(sheetId).data;
161	  const people = usePeople(sheetId).data;
162	  return useMemo(() => lateOf(settings, today, claims, people), [settings, today, claims, people]);
163	}
