18	export const periodsKey = (sheetId: string) => ['sheet', sheetId, 'periods'] as const;
19	
20	/** The sheet's periods, earliest first. */
21	export function usePeriods(sheetId: string) {
22	  return useQuery({
23	    queryKey: periodsKey(sheetId),
24	    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`),
25	  });
26	}
