28	/** The period whose dates contain the date (yyyy-mm-dd), or undefined when none does. */
29	export function periodOf(periods: Period[], date: string): Period | undefined {
30	  return periods.find((p) => p.from <= date && date <= p.to);
31	}
32	
33	/** A person's due-total for a period: while it is open, the dues (as shown on their rows now) of the person's claims
34	 *  that counted at the end of its last day (see countedAt) whose due-by falls in it; once closed or soft-closed, the figure fixed for them then (0.00 for a person
35	 *  added after). */
36	export function personPeriodDueTotal(period: Period, person: Person, claims: Claim[], people: Person[], rates: Rate[],
37	    floor: DatedValue, late: Late): string {
38	  if (period.closed || period.soft) return period.personTotals?.[String(person.id)] ?? '0.00';
39	  return sumDue(
40	    countedAt(claims.filter((c) => c.personId === person.id), people, period.to, late.today)
41	      .filter((c) => periodOf([period], dueBy(c)))
42	      .map((c) => claimDue(c, rateOn(rates, gradeOn(person, c.date), c.date, c.id), floor, late)),
43	  );
44	}
45	
46	/** A person's carried figure for a period: the dues (as shown on their rows now) of the person's claims that count
47	 *  (see countedAt) whose due-by falls in a period ending before this one starts, and whose status at the end of this
48	 *  period's last day (see statusAt) is OPEN or PENDING, added up, with their opening balance for it; once closed or soft-closed, the figure fixed for
49	 *  them then (0.00 for a person added after). */
50	export function personPeriodCarried(period: Period, periods: Period[], person: Person, claims: Claim[],
51	    people: Person[], rates: Rate[], floor: DatedValue, late: Late): string {
52	  if ((period.closed || period.soft) && period.personCarried) {
53	    const fixed = period.personCarried[String(person.id)];
54	    if (fixed !== undefined || period.personTotals?.[String(person.id)] === undefined) return fixed ?? '0.00';
55	  }
56	  const earlier = periods.filter((p) => p.to < period.from);
57	  return sumDue([
58	    ...countedAt(claims.filter((c) => c.personId === person.id), people, period.to, late.today)
59	      .filter((c) => { const at = statusAt(c, period.to); return at === 'OPEN' || at === 'PENDING'; })
60	      .filter((c) => periodOf(earlier, dueBy(c)))
61	      .map((c) => claimDue(c, rateOn(rates, gradeOn(person, c.date), c.date, c.id), floor, late)),
62	    period.personOpenings?.[String(person.id)] ?? '0.00',
63	  ]);
64	}
65	
66	/** A period's due-total as shown on its row: the people's due-totals for it (see personPeriodDueTotal) added up. */
67	export function periodDueTotal(period: Period, claims: Claim[], people: Person[], rates: Rate[], floor: DatedValue,
68	    late: Late): string {
69	  return sumDue(people.map((p) => personPeriodDueTotal(period, p, claims, people, rates, floor, late)));
70	}
71	
72	/** A period's classic due-total: while it is open, the dues (as shown on their rows now) of every person's claims that
73	 *  count by their status now (see live) whose due-by falls in it, added up; once closed or soft-closed, the figure
74	 *  fixed then (see personPeriodDueTotal). */
75	export function classicPeriodDueTotal(period: Period, claims: Claim[], people: Person[], rates: Rate[],
76	    floor: DatedValue, late: Late): string {
77	  if (period.closed || period.soft) return periodDueTotal(period, claims, people, rates, floor, late);
78	  return sumDue(people.flatMap((p) => live(claims.filter((c) => c.personId === p.id), [p], late.today)
79	    .filter((c) => periodOf([period], dueBy(c)))
80	    .map((c) => claimDue(c, rateOn(rates, gradeOn(p, c.date), c.date, c.id), floor, late))));
81	}
