22	/** The steward's dashboard: over the sheet, how many claims are PENDING, how many REVIEW, and how many
23	 *  overdue claims count (as the overdue rollup counts them). Anyone not acting as a steward sees the cells empty,
24	 *  and so does everyone while the screen shows the sheet as of a date. */
25	function Dashboard({ sheetId, user }: { sheetId: string; user: string }) {
