10	/** One read of a sheet as the store holds it now, or (asOf given, yyyy-mm-dd) as it stood at the end of that day,
11	 *  whatever date this screen shows its own sheet as of. Keyed under the sheet, so a load of that sheet re-reads it. */
12	function useNow<T>(sheetId: string, part: string, asOf = '') {
13	  return useQuery({
14	    queryKey: ['sheet', sheetId, 'now', part, asOf],
15	    queryFn: () => getJsonNow<T>(`/api/sheets/${encodeURIComponent(sheetId)}${part === '' ? '' : `/${part}`}`
16	      + (asOf === '' ? '' : `?asOf=${encodeURIComponent(asOf)}`)),
17	  });
18	}
19	
20	type Figures = { people: number; due: string; overdue: string };
21	
22	/** Adds the figures of sheets[at] to `sum`, then goes on to the next sheet; past the last, shows the figures added
23	 *  up. One component per sheet keeps each sheet's reads in hooks of its own. */
24	function Accumulate({ sheets, at, sum, asOf }: { sheets: string[]; at: number; sum: Figures; asOf: string }) {
25	  if (at >= sheets.length) return <Shown figures={sum} />;
26	  return <SheetFigures key={sheets[at]} sheets={sheets} at={at} sum={sum} asOf={asOf} />;
27	}
28	
29	/** A sheet's figures as it shows them now (or, asOf given, as it showed them at the end of that day, with that day
30	 *  as its today): its people (retired ones included), its due-total and its overdue-total (as its header shows
31	 *  them). */
32	function SheetFigures({ sheets, at, sum, asOf }: { sheets: string[]; at: number; sum: Figures; asOf: string }) {
33	  const sheetId = sheets[at];
34	  const people = useNow<Person[]>(sheetId, 'people', asOf).data ?? [];
35	  const claims = useNow<Claim[]>(sheetId, 'claims', asOf).data ?? [];
36	  const rates = useNow<Rate[]>(sheetId, 'rates', asOf).data ?? [];
37	  const settings = useNow<Settings>(sheetId, 'settings', asOf).data;
38	  const sheetToday = useNow<Sheet>(sheetId, '', asOf).data?.today ?? '';
39	  const today = asOf !== '' && sheetToday !== '' ? asOf : sheetToday;
40	  const floor = floorOf(settings);
41	  const late = lateOf(settings, today, claims, people);
42	  const next: Figures = {
43	    people: sum.people + people.length,
44	    due: sumDue([sum.due, sheetDueTotal(people, claims, rates, today, floor, late, settings?.cap ?? '')]),
45	    overdue: sumDue([sum.overdue, sheetOverdueTotal(people, claims, rates, late, floor)]),
46	  };
47	  return <Accumulate sheets={sheets} at={at + 1} sum={next} asOf={asOf} />;
48	}
