50	function Shown({ figures }: { figures: Figures }) {
51	  return (
52	    <p data-testid="consolidated">
53	      Consolidated: people <strong data-testid="consolidated-people-count">{figures.people}</strong>{' '}
54	      due total <strong data-testid="consolidated-due-total">{figures.due}</strong>{' '}
55	      overdue total <strong data-testid="consolidated-overdue-total">{figures.overdue}</strong>
56	    </p>
57	  );
58	}
59	
60	/** Consolidated figures over the sheet and all its descendants (its children — the sheets naming it as their
61	 *  parent — theirs, and so on), as the store holds them now (while this screen shows the sheet as of a date: every
62	 *  sheet of the tree as it stood at the end of that day, with that date as its today): the people, and each sheet's due-total and
63	 *  overdue-total (as that sheet shows them) added up. A sheet with no children shows its own. */
64	function Consolidated({ sheetId }: { sheetId: string; user: string }) {
65	  const [asOf] = useAsOf();
66	  const descendants = useNow<string[]>(sheetId, 'descendants').data ?? [];
67	  return <Accumulate sheets={[sheetId, ...descendants]} at={0} sum={{ people: 0, due: '0.00', overdue: '0.00' }}
68	    asOf={asOf ?? ''} />;
69	}
