    24	/** Refuse every change a viewer asks for on a sheet, and every change to an archived sheet, before any endpoint
    25	 *  reads or writes anything: each POST or PUT under a sheet (all but loading the sheet itself) whose signed-in user
    26	 *  (the body's {@code user}) is a viewer on that sheet, or on a sheet that is archived, is answered 403 with the
    27	 *  reason, and nothing is written or audited. A bulk open is left to its endpoint, which counts every selected claim
    28	 *  refused for a viewer or on an archived sheet, and so is a bulk reassign or bulk re-date; so is a viewer's bulk grade or bulk retire, which changes nobody, and a viewer's generating of the plans' claims, which makes none; so is a bulk settle by a viewer or on an archived sheet, which counts every selected claim refused. Every change sent from a
    29	 *  screen showing the sheet as of a date (the X-As-Of header), a bulk one included, is answered 403 the same way. */
    30	@Component
    31	public class RefuseViewerChanges extends OncePerRequestFilter {
    33	    /** A change under a sheet: /api/sheets/{sheetId}/... (loading the sheet, /api/sheets/{sheetId}, is not one). */
    34	    private static final Pattern CHANGE = Pattern.compile("^/api/sheets/([^/]+)/.+$");
    36	    /** A bulk open, left to the endpoint: it refuses each selected claim a viewer's role may not open (none), and
    37	     *  answers how many it opened and refused, writing nothing. */
    38	    private static final Pattern BULK_OPEN = Pattern.compile("^/api/sheets/[^/]+/bulk-(open|reassign|redate)$");
    40	    /** A bulk grade or retire, or generating the plans' claims, left to the endpoint for a viewer: it changes nothing
    41	     *  and answers that none was changed (none generated). */
    42	    private static final Pattern BULK_GRADE = Pattern.compile("^/api/sheets/[^/]+/(bulk-(grade|retire)|plans/generate)$");
    44	    /** A bulk settle, left to the endpoint for a viewer or on an archived sheet: it counts every selected claim refused. */
    45	    private static final Pattern BULK_SETTLE = Pattern.compile("^/api/sheets/[^/]+/bulk-settle$");
    47	    /** The header a screen showing the sheet as of a date sends every change with: the change is refused. */
    48	    public static final String AS_OF = "X-As-Of";
    50	    private final RoleRepository roles;
    51	    private final SheetRepository sheets;
    52	    private final JsonMapper json = JsonMapper.builder().build();
    54	    public RefuseViewerChanges(RoleRepository roles, SheetRepository sheets) {
    55	        this.roles = roles;
    56	        this.sheets = sheets;
    57	    }
    59	    @Override
    60	    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
    61	            throws ServletException, IOException {
    62	        String method = request.getMethod();
    63	        String path = request.getRequestURI().substring(request.getContextPath().length());
    64	        Matcher change = CHANGE.matcher(path);
    65	        if (method.equals("GET") || method.equals("HEAD") || method.equals("OPTIONS") || !change.matches()) {
    66	            chain.doFilter(request, response);
    67	            return;
    68	        }
    69	        String asOf = request.getHeader(AS_OF);
    70	        if (asOf != null && !asOf.isBlank()) {
    71	            response.setStatus(HttpServletResponse.SC_FORBIDDEN);
    72	            response.setContentType("text/plain;charset=UTF-8");
    73	            response.getWriter().write("The sheet is shown as of " + asOf.trim() + ": clear the as-of date to change it.");
    74	            return;
    75	        }
    76	        if (BULK_OPEN.matcher(path).matches()) {
    77	            chain.doFilter(request, response);
    78	            return;
    79	        }
    80	        byte[] body = request.getInputStream().readAllBytes();
    81	        String sheetId = URLDecoder.decode(change.group(1), StandardCharsets.UTF_8).trim();
    82	        String user = user(body);
    83	        if (user != null && !BULK_GRADE.matcher(path).matches() && !BULK_SETTLE.matcher(path).matches()
    84	                && Role.VIEWER.equals(roles.of(sheetId, user))) {
    85	            response.setStatus(HttpServletResponse.SC_FORBIDDEN);
    86	            response.setContentType("text/plain;charset=UTF-8");
    87	            response.getWriter().write("A viewer can change nothing on this sheet.");
    88	            return;
    89	        }
    90	        if (!BULK_SETTLE.matcher(path).matches() && sheets.archived(sheetId)) {
    91	            response.setStatus(HttpServletResponse.SC_FORBIDDEN);
    92	            response.setContentType("text/plain;charset=UTF-8");
    93	            response.getWriter().write("This sheet is archived: nothing on it can be changed.");
    94	            return;
    95	        }
    96	        chain.doFilter(new Rereadable(request, body), response);
    97	    }
