   173	/** A sheet's permission matrix: for each action the roles that may take it, as a comma separated list ('' when
   174	 *  blank: the standing rule applies — open, settle, void and close by clerk and steward; reassign and reopen by
   175	 *  steward). */
   176	public record Permissions(Map<String, String> roles) {
   177	
   178	    /** The actions the matrix covers, in order. */
   179	    public static final List<String> ACTIONS = List.of("open", "settle", "void", "reassign", "close", "reopen");
   180	
   181	    /** The standing rule for each action, used while its entry is blank. */
   182	    private static final Map<String, List<String>> STANDING = Map.of(
   183	            "open", List.of(Role.CLERK, Role.STEWARD), "settle", List.of(Role.CLERK, Role.STEWARD),
   184	            "void", List.of(Role.CLERK, Role.STEWARD), "close", List.of(Role.CLERK, Role.STEWARD),
   185	            "reassign", List.of(Role.STEWARD), "reopen", List.of(Role.STEWARD));
   186	
   187	    /** The entry for each action, in order ('' when blank). */
   188	    public Map<String, String> entries() {
   189	        Map<String, String> entries = new LinkedHashMap<>();
   190	        for (String action : ACTIONS) {
   191	            entries.put(action, roles.getOrDefault(action, ""));
   192	        }
   193	        return entries;
   194	    }
   195	
   196	    /** Whether the role may take the action. */
   197	    public boolean allows(String action, String role) {
   198	        String entry = roles.getOrDefault(action, "");
   199	        List<String> allowed = entry.isBlank() ? STANDING.getOrDefault(action, List.of())
   200	                : Arrays.stream(entry.split(",")).map(String::trim).toList();
   201	        return allowed.contains(role);
   202	    }
   203	}
