    28	/** For every plan on the sheet, in the order they were added, make a DRAFT claim of the plan's amount, dated that day
    29	 *  with an empty note, for every plan date (the start, then every N days; or a monthly plan's day in each month) up to the plan's end and the sheet's today
    30	 *  that the plan has made none for yet. Each is added as the claim form adds one — its CLAIM_ADDED line and then how
    31	 *  the sheet's figures moved over it — and a date the claim form would refuse (its rules, or after the person's
    32	 *  retirement date, or a due-by inside, or a date and due-by straddling, a period closed by hand) is skipped, to be tried again next time.
    33	 *  A viewer generates none: nothing is made or audited, and the answer is 0. */
    34	public class GeneratePlanClaims {
    35	    public void generate(@PathVariable("sheetId") String sheetId, @Val GenerateRequest request, PlanRepository plans,
    36	            PersonRepository people, SheetRepository sheets, SettingRepository settings, HolidayRepository holidays,
    37	            PeriodRepository periods, ClaimRepository claims, ClaimLogRepository log, Rollups rollups, Audit audit,
    38	            RoleRepository roles, Out<GenerateResponse> result) {
    39	        String sheet = sheetId.trim();
    40	        if (Role.VIEWER.equals(roles.of(sheet, request.user()))) {
    41	            result.set(new GenerateResponse(0));
    42	            return;
    43	        }
    44	        periods.lockSheet(sheet);
    45	        LocalDate today = sheets.today(sheet);
    46	        int made = 0;
    47	        for (Plan plan : plans.list(sheet)) {
    48	            Person person = people.find(sheet, plan.personId());
    49	            if (person == null || today == null) {
    50	                continue;
    51	            }
    52	            for (LocalDate date : plan.dates(today)) {
    53	                if (plans.made(plan.id(), date)) {
    54	                    continue;
    55	                }
    56	                ClaimInput claim;
    57	                try {
    58	                    claim = ClaimFormRules.check(new ClaimRequest(request.user(), plan.amount().toPlainString(),
    59	                            date.toString(), "", "", "", null));
    60	                    RetiredPersonException.refuse(person, date);
    61	                } catch (InvalidClaimException | RetiredPersonException e) {
    62	                    continue;
    63	                }
    64	                if (periods.closedByHandFor(sheet, date, DueBy.of(person, date, settings, sheets, holidays)) != null) {
    65	                    continue;
    66	                }
    67	                Rollup before = rollups.take(sheet);
    68	                Claim added = ClaimFormRules.add(claim, person, sheets, settings, holidays, periods, claims, log, audit);
    69	                rollups.record(sheet, request.user(), before);
    70	                plans.made(plan.id(), date, added.id());
    71	                made++;
    72	            }
    73	        }
    74	        result.set(new GenerateResponse(made));
    75	    }
    76	}
