   99	 *  given after it (it was added later). A claim with no log has its status now. */
  100	export function statusAt(c: Claim, day: string): ClaimStatus | null {
  101	  if (c.log.length === 0) return c.status;
  102	  let status: ClaimStatus | null = null;
  103	  for (const line of c.log) {
  104	    const m = /^(\S+) by .* on (\S*) due=\S+$/.exec(line);
  105	    if (m && (m[2] === '' || m[2] <= day)) status = m[1] as ClaimStatus;
