 4	/** The sheet's late charge as it is today: its late percent by date (a claim gains the one in force on each 30-day boundary past its due-by plus its grace; a claim is overdue past its own due-by, fixed when
 5	 *  it was created, plus its grace) and its today (null: none, so nothing is overdue) and each claim's grace (days: the
 6	 *  grace in force on its date of its person's grade in force on that date; 0 when none). */
 7	public record LateCharge(DatedAmount pct, LocalDate today, Rounding rounding, Grace grace) {
 8	
 9	    /** A claim's grace, in days. */
10	    @FunctionalInterface
11	    public interface Grace {
12	        int of(Claim claim);
13	
14	        /** No grace for any claim. */
15	        Grace NONE = claim -> 0;
16	
17	        /** The grace of the grade in force on a claim's date (its person's, by id, in `grades`) in force on that date,
18	         *  in the history. */
19	        static Grace of(SettingHistory history, Map<Long, Grades> grades) {
20	            return claim -> history.graceFor(grades.getOrDefault(claim.personId(), Grades.NONE).on(claim.date()),
21	                    claim.date());
22	        }
23	    }
24	
25	    /** The sheet's late charge as it is now. */
26	    public static LateCharge of(String sheetId, SettingRepository settings, SheetRepository sheets,
27	            ClaimRepository claims, PersonRepository people) {
28	        Map<Long, Grades> grades = people.list(sheetId).stream()
29	                .collect(Collectors.toMap(Person::id, Person::grades, (a, b) -> a));
30	        return new LateCharge(settings.latePct(sheetId), sheets.today(sheetId),
31	                Rounding.of(sheetId, settings, sheets, claims), Grace.of(settings.history(sheetId), grades));
32	    }
33	
34	    /** No late charge at all. */
35	    public static LateCharge none() {
36	        return new LateCharge(DatedAmount.always(BigDecimal.ZERO), null, Rounding.none(), Grace.NONE);
37	    }
38	
39	    /** The day a claim's late charge counts from: its due-by plus its grace. */
40	    public LocalDate lateFrom(Claim claim) {
41	        return claim.dueBy().plusDays(grace.of(claim));
42	    }
43	
44	    /** Whether a claim is overdue: it is OPEN or PENDING, not deferred on today, and its due-by plus its grace is
45	     *  before today. */
46	    public boolean overdue(Claim claim) {
47	        return claim.status().unsettled() && today != null && !claim.deferredOn(today)
48	                && lateFrom(claim).isBefore(today);
49	    }
50	
51	    /** The charge on a claim whose figure is `figure`: for each full 30 days it is overdue, the late percent in force
52	     *  on that boundary date (its due-by plus its grace plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries before it (compounding), each
53	     *  rounded to two decimals as the claim rounds (see Rounding), the charges added up (a boundary whose percent is 0.00 adds nothing); 0.00 when it is not
54	     *  overdue, or it is a correction (a negative amount), or its late charge was waived. */
55	    public BigDecimal on(Claim claim, BigDecimal figure) {
56	        BigDecimal total = new BigDecimal("0.00");
57	        if (!overdue(claim) || claim.amount().signum() < 0 || claim.waived()) {
58	            return total;
59	        }
60	        LocalDate from = lateFrom(claim);
61	        long periods = ChronoUnit.DAYS.between(from, today) / 30;
62	        for (long n = 1; n <= periods; n++) {
63	            BigDecimal pct = this.pct.on(from.plusDays(30 * n));
64	            if (pct.signum() != 0) {
65	                total = total.add(figure.add(total).multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding.of(claim)));
66	            }
67	        }
68	        return total;
69	    }
70	}

